window.__NLM_CHAPS = window.__NLM_CHAPS || {};
window.__NLM_CHAPS["vocab-ex-4-5"] = "<section class=\"chapter-section\" id=\"vocab-ex-4-5\">\n<h1>Bab 1B (Bagian 2): Strategi &amp; Latihan Soal Kosakata \u00b7 Mondai 4 &amp; Mondai 5</h1>\n<div class=\"info-box\"><strong>Panduan Belajar Bagian Ini (Gaya <em>Minna no Nihongo</em>):</strong><br>Bagian ini memuat <strong>Mondai 4 (<ruby>\u8a00<rt>\u3044</rt></ruby>\u3044<ruby>\u63db<rt>\u304b</rt></ruby>\u3048<ruby>\u985e<rt>\u308b\u3044</rt></ruby><ruby>\u7fa9<rt>\u304e</rt></ruby> / Persamaan Kata \u00b7 50 Soal Latihan + 1 Contoh)</strong> dan <strong>Mondai 5 (<ruby>\u7528<rt>\u3088\u3046</rt></ruby><ruby>\u6cd5<rt>\u307b\u3046</rt></ruby> / Penggunaan Kata \u00b7 54 Soal Latihan + 1 Contoh)</strong> dari buku asli (halaman buku 93-117; halaman PDF 96-120). Setiap soal disertai teks Jepang ber-<em>furigana</em>, kata bergaris bawah, terjemahan bahasa Indonesia, arti tiap pilihan, serta kunci jawaban (<code>\u6b63\u7b54</code>).</div>\n<h2>4. Mondai 4: Persamaan Kata / Sinonim (<ruby>\u8a00<rt>\u3044</rt></ruby>\u3044<ruby>\u63db<rt>\u304b</rt></ruby>\u3048<ruby>\u985e<rt>\u308b\u3044</rt></ruby><ruby>\u7fa9<rt>\u304e</rt></ruby>)</h2>\n<div class=\"tip-box\"><h3>\u3007 Contoh Soal &amp; Strategi Mondai 4 (\u554f\u984c4 \u4f8b \u00b7 Hal. Buku 93)</h3><p style=\"margin: 4px 0 8px 0;\"><strong>Instruksi Soal:</strong><br>\u554f\u984c4\u3000<u>\u3000\u3000\u3000</u>\u306b\u610f\u5473\u304c\u6700\u3082\u8fd1\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002<br><small style=\"color:#475569;\"><em>(Pilihlah satu kata yang artinya paling dekat dengan kata yang bergaris bawah dari pilihan 1, 2, 3, atau 4.)</em></small></p><div class=\"q-jp\"><span class=\"q-num\">\u4f8b</span>\u6bce\u65e5\u306e\u3088\u3046\u306b\u30e9\u30fc\u30e1\u30f3\u3092\u98df\u3079\u3066\u3044\u308b\u306e\u3067<u><ruby>\u98fd<rt>\u3042</rt></ruby>\u304d\u3066</u>\u3057\u307e\u3063\u305f\u3002</div><div class=\"q-id-trans\">Karena makan ramen hampir setiap hari, saya jadi bosan/muak.</div><div class=\"q-options\"><span class=\"opt\"><strong>1.</strong> \u3044\u3084\u306b\u306a\u3063\u3066 <small>(menjadi tidak suka / bosan)</small></span><span class=\"opt\"><strong>2.</strong> \u597d\u304d\u306b\u306a\u3063\u3066 <small>(menjadi suka)</small></span><span class=\"opt\"><strong>3.</strong> \u3084\u305b\u3066 <small>(menjadi kurus)</small></span><span class=\"opt\"><strong>4.</strong> \u592a\u3063\u3066 <small>(menjadi gemuk)</small></span></div><div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> 1</div><p style=\"margin: 8px 0 0 0;\"><strong>Penjelasan Strategi:</strong><br><span style=\"color:#0f172a;\"><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>4\u3067\u306f\u3001<ruby>\u4e0b<rt>\u304b</rt></ruby><ruby>\u7dda<rt>\u305b\u3093</rt></ruby>\u306e<ruby>\u8a00<rt>\u3053\u3068</rt></ruby><ruby>\u8449<rt>\u3070</rt></ruby>\u3068<ruby>\u6700<rt>\u3082\u3063\u3068</rt></ruby>\u3082<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u304c<ruby>\u8fd1<rt>\u3061\u304b</rt></ruby>\u3044<ruby>\u8a00<rt>\u3053\u3068</rt></ruby><ruby>\u8449<rt>\u3070</rt></ruby>\u3092<ruby>\u9078<rt>\u3048\u3089</rt></ruby>\u3076<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c5<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002\u3064\u307e\u308a\u3001<ruby>\u65e5<rt>\u306b</rt></ruby><ruby>\u672c<rt>\u307b\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3067<ruby>\u8a9e<rt>\u3054</rt></ruby><ruby>\u5f59<rt>\u3044</rt></ruby>\u306e<ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby>\u3092<ruby>\u8aac<rt>\u305b\u3064</rt></ruby><ruby>\u660e<rt>\u3081\u3044</rt></ruby>\u3059\u308b<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3067\u3059\u3002</span><br><span style=\"color:#1e3a8a;\">Pada <strong>Mondai 4</strong>, keluar <strong>5 soal</strong> yang meminta Anda memilih kata yang maknanya paling dekat dengan kata yang digarisbawahi. Dengan kata lain, ini adalah soal yang menjelaskan makna suatu kosakata dengan bahasa Jepang.</span></p></div>\n<h3>Latihan 1 \u00b7 Mondai 4: Kata Benda & Ungkapan (Hal. Buku 94-95)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c4\u3000<u>\u3000\u3000\u3000</u>\u306b\u610f\u5473\u304c\u6700\u3082\u8fd1\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu kata yang artinya paling dekat dengan kata yang bergaris bawah.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span>\u4ed6\u306e<u>\u307b\u3046\u307b\u3046</u>\u3092\u8003\u3048\u307e\u3057\u3087\u3046\u3002</div>\n  <div class=\"q-id-trans\">Mari kita pikirkan cara lain.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3058\u3087\u3046\u305f\u3044 <small>(keadaan / kondisi)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u610f<rt>\u3044</rt></ruby><ruby>\u5473<rt>\u307f</rt></ruby> <small>(arti / makna)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3084\u308a<ruby>\u65b9<rt>\u304b\u305f</rt></ruby> <small>(cara melakukan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u539f<rt>\u3052\u3093</rt></ruby><ruby>\u56e0<rt>\u3044\u3093</rt></ruby> <small>(penyebab)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><ruby>\u4e2d<rt>\u306a\u304b</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306f\u3001\u5143\u6c17\u3067\u660e\u308b\u3044<u><ruby>\u5370<rt>\u3044\u3093</rt></ruby><ruby>\u8c61<rt>\u3057\u3087\u3046</rt></ruby></u>\u3067\u3059\u3002</div>\n  <div class=\"q-id-trans\">Saudara Nakamoto memberi kesan yang bersemangat dan ceria.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u30a4\u30e1\u30fc\u30b8 <small>(image / kesan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6027\u683c <small>(sifat / kepribadian)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u30e1\u30f3\u30d0\u30fc <small>(anggota)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u4eba <small>(orang)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span>\u3053\u306e\u4ed5\u4e8b\u306f<u>\u5171\u540c\u3067</u>\u4f5c\u696d\u3057\u307e\u3057\u3087\u3046\u3002</div>\n  <div class=\"q-id-trans\">Untuk pekerjaan ini, mari kita kerjakan secara bersama-sama.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u4e00\u4eba\u3067 <small>(sendirian)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b <small>(bersama-sama)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u5f8c\u3067 <small>(nanti)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u5148\u306b <small>(lebih dulu)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><ruby>\u6751<rt>\u3080\u3089</rt></ruby><ruby>\u4e0a<rt>\u304b\u307f</rt></ruby>\u3055\u3093\u306f<u>\u3075\u3060\u3093</u>\u3001\u30b9\u30ab\u30fc\u30c8\u3092\u306f\u3044\u3066\u3044\u308b\u3002</div>\n  <div class=\"q-id-trans\">Saudari Murakami biasanya memakai rok.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3051\u3063\u304d\u3087\u304f <small>(pada akhirnya)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3068\u304d\u3069\u304d <small>(kadang-kadang)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3044\u3064\u3082 <small>(selalu / biasanya)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u521d\u3081\u3066 <small>(pertama kali)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span>\u5546\u54c1\u304c<u>\u308f\u308a\u3073\u304d\u306b\u306a\u3063\u3066\u3044\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Barang dagangannya sedang didiskon (potongan harga).</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u58f2\u308c\u3066\u7121\u304f\u306a\u3063\u3066\u3044\u308b <small>(habis terjual)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3042\u307e\u3063\u3066\u3044\u308b <small>(tersisa / berlebih)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u9ad8\u304f\u306a\u3063\u3066\u3044\u308b <small>(menjadi mahal)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u5b89\u304f\u306a\u3063\u3066\u3044\u308b <small>(menjadi murah)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><u>\u304b\u3093\u304b\u304f</u>\u3092\u3042\u3051\u3066\u304f\u3060\u3055\u3044\u3002</div>\n  <div class=\"q-id-trans\">Tolong beri jarak / sela.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3088\u3066\u3044 <small>(jadwal / rencana)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3042\u3044\u3060 <small>(jarak / sela / antara)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u307f\u3061 <small>(jalan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u305b\u304d <small>(tempat duduk)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span>\u3069\u306e\u5b66\u6821\u306b\u3082\u3001<u>\u304d\u305d\u304f</u>\u304c\u3042\u308b\u3002</div>\n  <div class=\"q-id-trans\">Di sekolah mana pun, terdapat peraturan.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u30b0\u30e9\u30a6\u30f3\u30c9 <small>(lapangan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u5236<rt>\u305b\u3044</rt></ruby><ruby>\u670d<rt>\u3075\u304f</rt></ruby> <small>(seragam)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u30eb\u30fc\u30eb <small>(aturan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u8a66<rt>\u3057</rt></ruby><ruby>\u9a13<rt>\u3051\u3093</rt></ruby> <small>(ujian)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span>\u7236\u306f\u3001\u58f0\u306b<u><ruby>\u7279<rt>\u3068\u304f</rt></ruby><ruby>\u5fb4<rt>\u3061\u3087\u3046</rt></ruby>\u304c\u3042\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Ayah memiliki ciri khas pada suaranya.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u81ea\u4fe1\u3092\u6301\u3063\u3066\u3044\u308b <small>(memiliki rasa percaya diri)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u4e0d\u6e80\u3092\u6301\u3063\u3066\u3044\u308b <small>(memiliki rasa tidak puas)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u4ed6\u3068\u306f<ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3046\u3068\u3053\u308d\u304c\u3042\u308b <small>(memiliki hal yang berbeda dari yang lain)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u4ed6\u3068\u540c\u3058\u3068\u3053\u308d\u304c\u3042\u308b <small>(memiliki hal yang sama dengan yang lain)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><u>\u5177\u5408</u>\u304c\u3042\u307e\u308a\u3088\u304f\u306a\u3044\u3002</div>\n  <div class=\"q-id-trans\">Kondisinya (badan/keadaan) kurang begitu baik.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u6210\u7e3e <small>(nilai / prestasi)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5929\u6c17 <small>(cuaca)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u7d50\u679c <small>(hasil)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u8abf\u5b50 <small>(kondisi / keadaan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">10</span><u><ruby>\u751f<rt>\u305b\u3044</rt></ruby><ruby>\u6d3b<rt>\u304b\u3064</rt></ruby><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u6163<rt>\u304b\u3093</rt></ruby></u>\u3092\u898b\u76f4\u3057\u307e\u3057\u3087\u3046\u3002</div>\n  <div class=\"q-id-trans\">Mari kita tinjau kembali kebiasaan hidup kita.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u305f\u307e\u306b<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u3063\u3066\u3044\u308b\u3053\u3068 <small>(hal yang dilakukan sesekali)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6bce\u65e5<ruby>\u884c<rt>\u304a\u3053\u306a</rt></ruby>\u3063\u3066\u3044\u308b\u3053\u3068 <small>(hal yang dilakukan setiap hari)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u305f\u307e\u306b\u3067\u304d\u308b\u3053\u3068 <small>(hal yang bisa dilakukan sesekali)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u6bce\u65e5\u3067\u304d\u308b\u3053\u3068 <small>(hal yang bisa dilakukan setiap hari)</small></span>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\u3000\u2461 1\u3000\u2462 2\u3000\u2463 3\u3000\u2464 4\u3000\u2465 2\u3000\u2466 3\u3000\u2467 3\u3000\u2468 4\u3000\u2469 2</div>\n<h3>Latihan 2 \u00b7 Mondai 4: Kata Kerja Golongan III (Hal. Buku 96-97)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c4\u3000<u>\u3000\u3000\u3000</u>\u306b\u610f\u5473\u304c\u6700\u3082\u8fd1\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu kata yang artinya paling dekat dengan kata yang bergaris bawah.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span>\u30a4\u30d9\u30f3\u30c8\u3092<u><ruby>\u5ef6<rt>\u3048\u3093</rt></ruby><ruby>\u671f<rt>\u304d</rt></ruby>\u3059\u308b</u>\u3053\u3068\u306b\u3057\u305f\u3002</div>\n  <div class=\"q-id-trans\">Kami memutuskan untuk menunda acara.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u65e9\u304f\u884c\u3046 <small>(melaksanakan lebih cepat)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5148\u306b\u306e\u3070\u3059 <small>(mengundur ke waktu nanti)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u65b0\u3057\u304f\u8003\u3048\u308b <small>(memikirkan yang baru)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u5168\u3066\u3084\u3081\u308b <small>(menghentikan semuanya)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span>\u65b0\u3057\u3044\u30d1\u30bd\u30b3\u30f3\u304c<u><ruby>\u6545<rt>\u3053</rt></ruby><ruby>\u969c<rt>\u3057\u3087\u3046</rt></ruby>\u3057\u305f</u>\u3002</div>\n  <div class=\"q-id-trans\">Komputer baru saya rusak.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3053\u308f\u308c\u305f <small>(rusak)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u51fa\u305f <small>(keluar / muncul)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u58f2\u308c\u305f <small>(terjual)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3068\u3069\u3044\u305f <small>(tiba / sampai)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span>\u5144\u306b\u3001\u81ea\u8ee2\u8eca\u3092<u><ruby>\u4fee<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u3057\u3066</u>\u3082\u3089\u3046\u3002</div>\n  <div class=\"q-id-trans\">Saya meminta kakak laki-laki memperbaiki sepeda saya.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u8cb7\u3063\u3066 <small>(membelikan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u306a\u304a\u3057\u3066 <small>(memperbaiki)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u964d<rt>\u304a</rt></ruby>\u308a\u3066 <small>(turun)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u304b\u3057\u3066 <small>(meminjamkan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span>\u30d3\u30eb\u3092<u>\u3051\u3093\u305b\u3064\u3059\u308b</u>\u305d\u3046\u3060\u3002</div>\n  <div class=\"q-id-trans\">Katanya mereka akan membangun gedung.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u8cb8\u3059 <small>(meminjamkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3053\u308f\u3059 <small>(merusak / merobohkan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u305f\u3066\u308b <small>(membangun / mendirikan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u501f\u308a\u308b <small>(meminjam / menyewa)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span>\u7d50\u679c\u3092<u>\u307b\u3046\u3053\u304f\u3059\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Melaporkan hasilnya.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u77e5\u3089\u305b\u308b <small>(memberitahukan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u78ba\u304b\u3081\u308b <small>(memastikan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u6b8b\u3059 <small>(menyisakan / meninggalkan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u51fa\u3059 <small>(mengeluarkan / menyerahkan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span>\u30a2\u30f3\u30b1\u30fc\u30c8\u3092<u>\u304b\u3044\u3057\u3085\u3046\u3059\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Mengumpulkan kuesioner/angket.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u4f5c\u308b <small>(membuat)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u66f8\u304f <small>(menulis)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u914d<rt>\u304f\u3070</rt></ruby>\u308b <small>(membagikan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u96c6\u3081\u308b <small>(mengumpulkan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span>\u30b5\u30fc\u30d3\u30b9\u3092<u>\u308a\u3088\u3046\u3059\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Menggunakan / memanfaatkan layanan.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u4e2d\u6b62\u3059\u308b <small>(menghentikan / membatalkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u59cb\u3081\u308b <small>(memulai)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u7528\u610f\u3059\u308b <small>(menyiapkan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u4f7f\u3046 <small>(menggunakan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span>\u4f1a\u8b70\u3092<u>\u3057\u3093\u3053\u3046\u3059\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Memandu / melancarkan jalannya rapat.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u898b\u5b66\u3059\u308b <small>(meninjau / mengamati)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6e96\u5099\u3059\u308b <small>(mempersiapkan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3059\u3059\u3081\u308b <small>(memajukan / melanjutkan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u304a\u308f\u3089\u305b\u308b <small>(mengakhiri)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span>50\u30e1\u30fc\u30c8\u30eb\u306e\u6a4b\u3092<u><ruby>\u5f80<rt>\u304a\u3046</rt></ruby><ruby>\u5fa9<rt>\u3075\u304f</rt></ruby>\u3059\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Menyeberang bolak-balik jembatan sepanjang 50 meter.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u6700\u5f8c\u307e\u3067<ruby>\u6e21<rt>\u308f\u305f</rt></ruby>\u308b <small>(menyeberang sampai akhir)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u884c\u3063\u3066<ruby>\u623b<rt>\u3082\u3069</rt></ruby>\u308b <small>(pergi lalu kembali)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u8d70\u308b <small>(berlari)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u6b69\u304f <small>(berjalan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">10</span><u>\u304b\u3093\u305d\u3046\u3055\u305b\u305f</u>\u98df\u3079\u7269\u306b\u306f\u3001<ruby>\u6804<rt>\u3048\u3044</rt></ruby><ruby>\u990a<rt>\u3088\u3046</rt></ruby>\u304c\u3042\u308b\u3002</div>\n  <div class=\"q-id-trans\">Makanan yang dikeringkan mengandung nutrisi/gizi.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3084\u3044\u305f <small>(yang dipanggang / dibakar)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u306b\u305f <small>(yang direbus / dimasak)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u304b\u308f\u304b\u3057\u305f <small>(yang dikeringkan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3042\u305f\u305f\u3081\u305f <small>(yang dihangatkan)</small></span>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 1\u3000\u2462 2\u3000\u2463 3\u3000\u2464 1\u3000\u2465 4\u3000\u2466 4\u3000\u2467 3\u3000\u2468 2\u3000\u2469 3</div>\n<h3>Latihan 3 \u00b7 Mondai 4: Kata Kerja (Hal. Buku 98-99)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c4\u3000<u>\u3000\u3000\u3000</u>\u306b\u610f\u5473\u304c\u6700\u3082\u8fd1\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu kata yang artinya paling dekat dengan kata yang bergaris bawah.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span>\u5148\u751f\u304c\u6025\u306b<u>\u3060\u307e\u3063\u305f</u>\u3002</div>\n  <div class=\"q-id-trans\">Guru tiba-tiba terdiam.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u6012\u308a\u306f\u3058\u3081\u305f <small>(mulai marah)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5927\u304d\u306a\u58f0\u3092\u51fa\u3057\u305f <small>(mengeluarkan suara keras)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u6ce3\u304d\u51fa\u3057\u305f <small>(mulai menangis)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u4f55\u3082\u8a00\u308f\u306a\u304f\u306a\u3063\u305f <small>(tidak mengatakan apa-apa lagi)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span>\u3044\u3064\u307e\u3067\u305f\u3063\u3066\u3082<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u304c\u5f85\u3061\u5408\u308f\u305b\u306e\u5834\u6240\u306b\u6765\u306a\u3044\u306e\u3067\u3001<u>\u304f\u305f\u3073\u308c\u3066</u>\u3057\u307e\u3063\u305f\u3002</div>\n  <div class=\"q-id-trans\">Karena teman tidak kunjung datang ke tempat janjian, saya jadi kelelahan.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u6012<rt>\u304a\u3053</rt></ruby>\u3063\u3066 <small>(marah)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u5e30<rt>\u304b\u3048</rt></ruby>\u3063\u3066 <small>(pulang)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u56f0<rt>\u3053\u307e</rt></ruby>\u3063\u3066 <small>(bingung / kesulitan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066 <small>(lelah)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span>\u304a\u3082\u3061\u3083\u3092<u><ruby>\u7247<rt>\u304b\u305f</rt></ruby><ruby>\u4ed8<rt>\u3065</rt></ruby>\u3051\u3066\u304f\u3060\u3055\u3044</u>\u3002</div>\n  <div class=\"q-id-trans\">Tolong rapikan/bereskan mainannya.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u5e83\u3052\u3066\u304f\u3060\u3055\u3044 <small>(tolong bentangkan / sebarkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u6574<rt>\u305b\u3044</rt></ruby><ruby>\u7406<rt>\u308a</rt></ruby>\u3057\u3066\u304f\u3060\u3055\u3044 <small>(tolong rapikan / tata)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u8cb7\u3063\u3066\u304f\u3060\u3055\u3044 <small>(tolong belikan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u6e96\u5099\u3057\u3066\u304f\u3060\u3055\u3044 <small>(tolong siapkan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span>\u7528\u4e8b\u3092<u><ruby>\u6e08<rt>\u3059</rt></ruby>\u307e\u305b\u3066</u>\u304b\u3089\u3001\u305d\u3061\u3089\u306b\u5411\u304b\u3044\u307e\u3059\u3002</div>\n  <div class=\"q-id-trans\">Setelah menyelesaikan urusan, saya akan menuju ke sana.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u5165\u308c\u3066 <small>(memasukkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u65ad\u3063\u3066 <small>(menolak)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u601d\u3044\u51fa\u3057\u3066 <small>(mengingat kembali)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u7d42\u308f\u3089\u305b\u3066 <small>(menyelesaikan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span>\u3053\u306e\u4ed5\u4e8b\u306f\u3001<ruby>\u7c21<rt>\u304b\u3093</rt></ruby><ruby>\u5358<rt>\u305f\u3093</rt></ruby>\u306a\u4f5c\u696d\u306a\u306e\u3067\u3059\u3050\u306b<u><ruby>\u6163<rt>\u306a</rt></ruby>\u308c\u308b</u>\u3068\u601d\u3044\u307e\u3059\u3002</div>\n  <div class=\"q-id-trans\">Karena pekerjaan ini adalah tugas yang sederhana, saya rasa Anda akan segera terbiasa (menguasainya).</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u697d\u3057\u304f\u306a\u308b <small>(menjadi menyenangkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u8f9b<rt>\u3064\u3089</rt></ruby>\u304f\u306a\u308b <small>(menjadi berat / menyakitkan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u4e0a\u624b\u306b\u306a\u308b <small>(menjadi mahir / terampil)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u4e0b\u624b\u306b\u306a\u308b <small>(menjadi tidak terampil)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span>\u5c0f\u3055\u3044\u5f1f\u3092<u>\u304b\u307e\u3046</u>\u3002</div>\n  <div class=\"q-id-trans\">Mengurus / menemani adik laki-laki yang masih kecil.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u6ce8\u610f\u3059\u308b <small>(memperingatkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u7b11\u308f\u305b\u308b <small>(membuat tertawa)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u4e16\u8a71\u3059\u308b <small>(merawat / mengurus)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u6ce3\u304b\u305b\u308b <small>(membuat menangis)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span>3\u6642\u9593\u3082\u6642\u9593\u304c<u><ruby>\u7d4c<rt>\u305f</rt></ruby>\u3063\u305f</u>\u3002</div>\n  <div class=\"q-id-trans\">Waktu sudah berlalu selama 3 jam.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u904e<rt>\u3059</rt></ruby>\u304e\u305f <small>(berlalu / lewat)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6b8b\u3063\u305f <small>(tersisa)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3042\u3063\u305f <small>(ada)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u306a\u304b\u3063\u305f <small>(tidak ada)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span>\u3053\u306e\u30a2\u30d7\u30ea\u306f\u3001\u82f1\u8a9e\u3092<u>\u8a33\u3059</u>\u3053\u3068\u304c\u3067\u304d\u308b\u3002</div>\n  <div class=\"q-id-trans\">Aplikasi ini dapat menerjemahkan bahasa Inggris.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u8abf\u3079\u308b <small>(memeriksa / mencari tahu)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u899a\u3048\u308b <small>(mengingat / menghafal)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u4ed6\u306e\u56fd\u306e\u8a00\u8449\u306b\u5909\u3048\u308b <small>(mengubah ke bahasa negara lain)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u4ed6\u306e\u56fd\u306e\u8a00\u8449\u3067\u52c9\u5f37\u3059\u308b <small>(belajar dengan bahasa negara lain)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span>\u65b0\u3057\u3044\u30e1\u30f3\u30d0\u30fc\u3092<u><ruby>\u52a0<rt>\u304f\u308f</rt></ruby>\u3048\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Menambahkan anggota baru.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u8db3\u3059 <small>(menambah)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6c7a\u3081\u308b <small>(menentukan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u5909\u3048\u308b <small>(mengubah)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u96c6\u3081\u308b <small>(mengumpulkan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">10</span><u>\u3069\u306a\u308b</u>\u306e\u306f\u3088\u304f\u306a\u3044\u3053\u3068\u3060\u3002</div>\n  <div class=\"q-id-trans\">Membentak / berteriak dengan marah adalah hal yang tidak baik.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby>\u3092\u304b\u3051\u308b <small>(merepotkan / mengganggu)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5927\u304d\u306a\u58f0\u3067\u304a\u3053\u308b <small>(memarahi dengan suara keras)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u5931\u793c\u306a\u3053\u3068\u3092\u8a00\u3046 <small>(mengatakan hal yang tidak sopan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3046\u305d\u3092\u3064\u304f <small>(berbohong)</small></span>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\u3000\u2461 4\u3000\u2462 2\u3000\u2463 4\u3000\u2464 3\u3000\u2465 3\u3000\u2466 1\u3000\u2467 3\u3000\u2468 1\u3000\u2469 2</div>\n<h3>Latihan 4 \u00b7 Mondai 4: Kata Sifat & Kata Keterangan (Hal. Buku 100-101)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c4\u3000<u>\u3000\u3000\u3000</u>\u306b\u610f\u5473\u304c\u6700\u3082\u8fd1\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu kata yang artinya paling dekat dengan kata yang bergaris bawah.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span>\u6bce\u65e5<u>\u3060\u3089\u3057\u306a\u3044</u>\u751f\u6d3b\u3092\u3057\u3066\u3044\u308b\u3002</div>\n  <div class=\"q-id-trans\">Setiap hari menjalani hidup yang berantakan / tidak disiplin.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u697d\u3057\u3044 <small>(menyenangkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u304d\u3061\u3093\u3068\u3057\u3066\u3044\u306a\u3044 <small>(tidak rapi / tidak teratur)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u697d\u3057\u304f\u306a\u3044 <small>(tidak menyenangkan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u304d\u3061\u3093\u3068\u3057\u305f <small>(rapi / teratur)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span>\u5f7c\u5973\u306f\u3001\u4e0a\u54c1\u3067<u>\u304a\u3068\u306a\u3057\u3044</u>\u4eba\u3067\u3059\u3002</div>\n  <div class=\"q-id-trans\">Dia adalah orang yang anggun/elegan dan pendiam.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u9759<rt>\u3057\u305a</rt></ruby>\u304b\u306a <small>(tenang / pendiam)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u512a\u3057\u3044 <small>(baik hati / lembut)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u304d\u308c\u3044\u306a <small>(cantik / bersih)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u660e\u308b\u3044 <small>(ceria)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><ruby>\u606f\u5b50<rt>\u3080\u3059\u3053</rt></ruby>\u306f\u3001<ruby>\u866b<rt>\u3080\u3057</rt></ruby>\u306b\u3064\u3044\u3066<u><ruby>\u8a73<rt>\u304f\u308f</rt></ruby>\u3057\u3044</u>\u3002</div>\n  <div class=\"q-id-trans\">Anak laki-laki saya sangat paham tentang serangga.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3042\u307e\u308a\u77e5\u3089\u306a\u3044 <small>(tidak terlalu tahu)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3088\u304f\u8a71\u3057\u3066\u3044\u308b <small>(sering membicarakan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3088\u304f\u77e5\u3063\u3066\u3044\u308b <small>(tahu dengan baik / sangat paham)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3042\u307e\u308a\u8a71\u3055\u306a\u3044 <small>(jarang berbicara)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span>\u9577\u3044<ruby>\u8ddd<rt>\u304d\u3087</rt></ruby><ruby>\u96e2<rt>\u308a</rt></ruby>\u3092\u8d70\u308b\u3053\u3068\u306f<u>\u304d\u3064\u3044</u>\u3002</div>\n  <div class=\"q-id-trans\">Berlari jarak jauh itu berat / melelahkan.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u697d<rt>\u305f\u306e</rt></ruby>\u3057\u3044 <small>(menyenangkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3064\u3089\u3044 <small>(berat / menyakitkan)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u5371<rt>\u3042\u3076</rt></ruby>\u306a\u3044 <small>(berbahaya)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3048\u3089\u3044 <small>(hebat / terpuji)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span>\u6bcd\u304b\u3089\u3001<u>\u3081\u305a\u3089\u3057\u3044</u>\u54c1\u7269\u3092\u3082\u3089\u3063\u305f\u3002</div>\n  <div class=\"q-id-trans\">Saya menerima barang yang langka/unik dari ibu.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3044\u3089\u306a\u3044 <small>(tidak dibutuhkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3069\u3053\u306b\u3067\u3082\u3042\u308b <small>(ada di mana saja)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u6b32\u3057\u304b\u3063\u305f <small>(yang diinginkan)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3042\u307e\u308a\u898b\u305f\u3053\u3068\u306e\u306a\u3044 <small>(yang jarang terlihat)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span>\u65e5\u672c\u4eba\u3067\u3082\u3001<u>\u591a\u5c11</u>\u6f22\u5b57\u3092<ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3048\u308b\u3053\u3068\u306f\u3042\u308b\u3002</div>\n  <div class=\"q-id-trans\">Orang Jepang sekalipun, ada kalanya sedikit salah dalam kanji.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u305f\u304f\u3055\u3093 <small>(banyak)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5c11\u3057 <small>(sedikit)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u591a\u304f\u306e <small>(banyak ...)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u5168\u3066\u306e <small>(semua ...)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span>\u6628\u65e5\u306e\u3051\u3093\u304b\u306e\u3053\u3068\u306f\u3001<u>\u3061\u3063\u3068\u3082</u>\u6c17\u306b\u3057\u3066\u306a\u3044\u3088\u3002</div>\n  <div class=\"q-id-trans\">Tentang pertengkaran kemarin, saya sama sekali tidak memikirkannya, kok.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby> <small>(sama sekali tidak)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6b63\u76f4 <small>(jujur)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3057\u3070\u3089\u304f <small>(sementara waktu)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u76f8\u5909\u308f\u3089\u305a <small>(masih tetap sama)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span>\u3053\u306e\u30de\u30f3\u30ac\u306f\u3001<u>\u306a\u304b\u306a\u304b</u>\u304a\u3082\u3057\u308d\u3044\u3002</div>\n  <div class=\"q-id-trans\">Komik ini lumayan / cukup menarik.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u7279<rt>\u3068\u304f</rt></ruby>\u306b <small>(khususnya)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u76f8<rt>\u305d\u3046</rt></ruby><ruby>\u5f53<rt>\u3068\u3046</rt></ruby> <small>(cukup / lumayan / sangat)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u7d76<rt>\u305c\u3063</rt></ruby><ruby>\u5bfe<rt>\u305f\u3044</rt></ruby> <small>(pasti / mutlak)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u305f\u307e\u306b <small>(sesekali)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span>\u3053\u306e\u672c\u306f\u3001<u>\u307b\u3068\u3093\u3069</u>\u8aad\u307f\u7d42\u308f\u3063\u3066\u3044\u308b\u3002</div>\n  <div class=\"q-id-trans\">Buku ini hampir selesai saya baca.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u521d\u3081\u3066 <small>(pertama kali)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5341\u5206 <small>(cukup)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u305f\u3044\u3066\u3044 <small>(sebagian besar / hampir seluruhnya)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u304d\u3061\u3093\u3068 <small>(dengan rapi / teratur)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">10</span>\u5927\u304d\u304b\u3063\u305f\u304d\u305a\u53e3\u304c<u>\u3060\u3093\u3060\u3093</u><ruby>\u6cbb<rt>\u306a\u304a</rt></ruby>\u3063\u3066\u304d\u305f\u3002</div>\n  <div class=\"q-id-trans\">Luka yang tadinya besar lambat laun mulai sembuh.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u6025\u306b <small>(tiba-tiba)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u5c11\u3057\u305a\u3064 <small>(sedikit demi sedikit)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3055\u3063\u305d\u304f <small>(segera)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u304b\u306a\u308a <small>(cukup / lumayan)</small></span>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 1\u3000\u2462 3\u3000\u2463 2\u3000\u2464 4\u3000\u2465 2\u3000\u2466 1\u3000\u2467 2\u3000\u2468 3\u3000\u2469 2</div>\n<h3>Latihan 5 \u00b7 Mondai 4: Onomatope & Kata Serapan Katakana (Hal. Buku 102-103)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c4\u3000<u>\u3000\u3000\u3000</u>\u306b\u610f\u5473\u304c\u6700\u3082\u8fd1\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu kata yang artinya paling dekat dengan kata yang bergaris bawah.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span>\u304b\u305c<ruby>\u85ac<rt>\u3050\u3059\u308a</rt></ruby>\u3092\u98f2\u3093\u3067\u3001<u>\u3050\u3063\u3059\u308a</u><ruby>\u7720<rt>\u306d\u3080</rt></ruby>\u308b\u3002</div>\n  <div class=\"q-id-trans\">Minum obat flu, lalu tidur dengan nyenyak.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u6d45\u304f <small>(dengan dangkal / tidak nyenyak)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6df1\u304f <small>(dengan lelap / dalam)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u65e9\u304f <small>(cepat)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u9045<rt>\u304a\u305d</rt></ruby>\u304f <small>(lambat / larut)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><ruby>\u9589<rt>\u3078\u3044</rt></ruby><ruby>\u5e97<rt>\u3066\u3093</rt></ruby><ruby>\u524d<rt>\u307e\u3048</rt></ruby>\u306e\u5e97\u5185\u306f\u3001<u>\u304c\u3089\u304c\u3089\u3060</u>\u3002</div>\n  <div class=\"q-id-trans\">Bagian dalam toko menjelang tutup sangat sepi (kosong).</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u7a7a<rt>\u3059</rt></ruby>\u3044\u3066\u3044\u308b <small>(kosong / sepi)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u7a7a<rt>\u3042</rt></ruby>\u3044\u3066\u3044\u306a\u3044 <small>(tidak kosong / penuh)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u6c5a<rt>\u3088\u3054</rt></ruby>\u308c\u3066\u3044\u308b <small>(kotor)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u6c5a<rt>\u3088\u3054</rt></ruby>\u308c\u3066\u3044\u306a\u3044 <small>(tidak kotor)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span>\u5f1f\u306f\u304a\u6bcd\u3055\u3093\u3068\u9854\u304c<u>\u305d\u3063\u304f\u308a\u3060</u>\u3002</div>\n  <div class=\"q-id-trans\">Wajah adik laki-laki mirip sekali dengan ibu.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u4f3c<rt>\u306b</rt></ruby>\u3066\u3044\u306a\u3044 <small>(tidak mirip)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3061\u3087\u3063\u3068<ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3046 <small>(sedikit berbeda)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u4f3c<rt>\u306b</rt></ruby>\u3066\u3044\u308b <small>(mirip)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u5168<rt>\u307e\u3063\u305f</rt></ruby>\u304f<ruby>\u540c<rt>\u304a\u306a</rt></ruby>\u3058\u3060 <small>(persis sama sekali)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span>\u610f\u898b\u304c<u>\u3070\u3089\u3070\u3089\u3060</u>\u3002</div>\n  <div class=\"q-id-trans\">Pendapatnya berbeda-beda / terpecah.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u3060 <small>(sama)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6b63\u3057\u3044 <small>(benar)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3063\u3066\u3044\u308b <small>(salah)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3079\u3064\u3079\u3064\u3060 <small>(terpisah / berbeda-beda)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><u>\u305d\u3063\u3068</u>\u30c9\u30a2\u3092<ruby>\u9589<rt>\u3057</rt></ruby>\u3081\u305f\u3002</div>\n  <div class=\"q-id-trans\">Menutup pintu dengan pelan / diam-diam.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u5f37\u304f <small>(dengan kuat)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u78ba\u304b\u306b <small>(dengan pasti)</small></span>\n    <span class=\"opt\"><strong>3.</strong> <ruby>\u9759<rt>\u3057\u305a</rt></ruby>\u304b\u306b <small>(dengan pelan / tenang)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u65e9\u901f <small>(segera)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span>\u3044\u308d\u3044\u308d\u306a\u304f\u3060\u3082\u306e\u3092<u>\u30df\u30c3\u30af\u30b9\u3059\u308b</u>\u3002</div>\n  <div class=\"q-id-trans\">Mencampurkan berbagai macam buah-buahan.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u3053\u304a\u3089\u305b\u308b <small>(membekukan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u306b\u308b <small>(merebus)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u307e\u305c\u308b <small>(mencampur)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u3044\u305f\u3081\u308b <small>(menumis)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span>\u793e\u9577\u5ba4\u306e\u30c9\u30a2\u3092<u>\u30ce\u30c3\u30af\u3057\u307e\u3057\u305f</u>\u3002</div>\n  <div class=\"q-id-trans\">Saya mengetuk pintu ruang direktur.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u958b\u3051\u307e\u3057\u305f <small>(membuka)</small></span>\n    <span class=\"opt\"><strong>2.</strong> <ruby>\u9589<rt>\u3057</rt></ruby>\u3081\u307e\u3057\u305f <small>(menutup)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3053\u308f\u3057\u307e\u3057\u305f <small>(merusak)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u305f\u305f\u304d\u307e\u3057\u305f <small>(mengetuk / memukul pelan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span>\u304b\u307f\u306e\u6bdb\u3092<u>\u30ab\u30c3\u30c8\u3057\u305f</u>\u3002</div>\n  <div class=\"q-id-trans\">Saya memotong rambut.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u304b\u308f\u304b\u3057\u305f <small>(mengeringkan)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u6d17\u3063\u305f <small>(mencuci)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u5207\u3063\u305f <small>(memotong)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u306e\u3070\u3057\u305f <small>(memanjangkan)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><u>\u30ea\u30d3\u30f3\u30b0</u>\u3067\u3086\u3063\u304f\u308a\u3068<ruby>\u904e<rt>\u3059</rt></ruby>\u3054\u3059\u3002</div>\n  <div class=\"q-id-trans\">Menghabiskan waktu dengan santai di ruang keluarga.</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> \u306d\u308b\u90e8\u5c4b <small>(kamar tidur)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u3075\u308d <small>(kamar mandi)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u306b\u308f <small>(halaman / taman)</small></span>\n    <span class=\"opt\"><strong>4.</strong> <ruby>\u5c45<rt>\u3044</rt></ruby><ruby>\u9593<rt>\u307e</rt></ruby> <small>(ruang keluarga / ruang tamu)</small></span>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">10</span>\u304a\u5e97\u304c<u>\u30aa\u30fc\u30d7\u30f3\u3059\u308b</u>\u306e\u306f\u3044\u3064\u3067\u3059\u304b\u3002</div>\n  <div class=\"q-id-trans\">Kapan tokonya mulai buka?</div>\n  <div class=\"q-options\">\n    <span class=\"opt\"><strong>1.</strong> <ruby>\u9589<rt>\u3057</rt></ruby>\u307e\u308b <small>(tutup)</small></span>\n    <span class=\"opt\"><strong>2.</strong> \u958b\u304f <small>(buka)</small></span>\n    <span class=\"opt\"><strong>3.</strong> \u3067\u304d\u308b <small>(jadi / selesai dibangun)</small></span>\n    <span class=\"opt\"><strong>4.</strong> \u306a\u304f\u306a\u308b <small>(hilang / habis)</small></span>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\u3000\u2461 1\u3000\u2462 3\u3000\u2463 4\u3000\u2464 3\u3000\u2465 3\u3000\u2466 4\u3000\u2467 3\u3000\u2468 4\u3000\u2469 2</div>\n<p style=\"font-size:8.8pt; color:#64748b; font-style:italic; margin:6px 0 18px 0;\">Catatan: Halaman buku 104 (halaman PDF 107) pada edisi asli merupakan halaman kosong pemisah sebelum Mondai 5.</p>\n<h2>5. Mondai 5: Penggunaan Kata (<ruby>\u7528<rt>\u3088\u3046</rt></ruby><ruby>\u6cd5<rt>\u307b\u3046</rt></ruby>)</h2>\n<div class=\"tip-box\"><h3>\u3007 Contoh Soal &amp; Strategi Mondai 5 (\u554f\u984c5 \u4f8b \u00b7 Hal. Buku 105)</h3><p style=\"margin: 4px 0 8px 0;\"><strong>Instruksi Soal:</strong><br>\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002<br><small style=\"color:#475569;\"><em>(Pilihlah satu kalimat dengan penggunaan kata berikut yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></small></p><div class=\"q-jp\"><span class=\"q-num\">\u4f8b</span><strong>\u914d\u9054</strong>\uff08\u306f\u3044\u305f\u3064\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pengantaran / pengiriman (barang, paket, surat))</small></div><div class=\"q-options\">  <div class=\"opt-block\">    <div class=\"q-jp\">1. \u51fa\u5f35\u306b\u884c\u3063\u3066\u3044\u305f\u7236\u304c\u3001\u591c\u9045\u304f\u306b<u>\u914d\u9054</u>\u3057\u305f\u3002</div>    <div class=\"q-id-trans\">Ayah yang pergi dinas luar kota telah mengantarkan (barang) larut malam.</div>  </div>  <div class=\"opt-block\">    <div class=\"q-jp\">2. 50\u500b\u306e\u8377\u7269\u3092\u3001\u99c5\u524d\u306e\u5e97\u306b<u>\u914d\u9054</u>\u3059\u308b\u3002</div>    <div class=\"q-id-trans\">Mengantarkan 50 buah barang/paket ke toko di depan stasiun.</div>  </div>  <div class=\"opt-block\">    <div class=\"q-jp\">3. \u6628\u65e5\u3001\u5e97\u306b\u6709\u540d\u306a\u6b4c\u624b\u304c<u>\u914d\u9054</u>\u3057\u305f\u3002</div>    <div class=\"q-id-trans\">Kemarin, seorang penyanyi terkenal mengantarkan (barang) ke toko.</div>  </div>  <div class=\"opt-block\">    <div class=\"q-jp\">4. \u3053\u306e\u98db\u884c\u6a5f\u306f\u3001\u3042\u306830\u5206\u307b\u3069\u3067<ruby>\u6771<rt>\u3068\u3046</rt></ruby><ruby>\u4eac<rt>\u304d\u3087\u3046</rt></ruby>\u306b<u>\u914d\u9054</u>\u3059\u308b\u3002</div>    <div class=\"q-id-trans\">Pesawat ini akan mengantarkan ke Tokyo sekitar 30 menit lagi.</div>  </div></div><div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> 2\uff081 \u5e30\u5b85 [pulang ke rumah]\u30fb3 \u6765\u5e97 [datang ke toko]\u30fb4 \u5230\u7740 [tiba/sampai]\uff09</div><p style=\"margin: 8px 0 0 0;\"><strong>Penjelasan Strategi:</strong><br><span style=\"color:#0f172a;\"><ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>5\u3067\u306f\u3001<ruby>\u4e00<rt>\u3072\u3068</rt></ruby>\u3064\u306e<ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u304c<ruby>\u6b63<rt>\u305f\u3060</rt></ruby>\u3057\u304f<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u308f\u308c\u3066\u3044\u308b<ruby>\u6587<rt>\u3076\u3093</rt></ruby><ruby>\u7ae0<rt>\u3057\u3087\u3046</rt></ruby>\u3092<ruby>\u9078<rt>\u3048\u3089</rt></ruby>\u3076<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u304c5<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u51fa<rt>\u3067</rt></ruby>\u307e\u3059\u3002<ruby>\u9078<rt>\u305b\u3093</rt></ruby><ruby>\u629e<rt>\u305f\u304f</rt></ruby><ruby>\u80a2<rt>\u3057</rt></ruby>4\u3064\u306f<ruby>\u5168<rt>\u3059\u3079</rt></ruby>\u3066<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3068\u3057\u3066<ruby>\u51fa<rt>\u3060</rt></ruby>\u3055\u308c\u3066\u3044\u308b<ruby>\u8a9e<rt>\u3054</rt></ruby><ruby>\u5f59<rt>\u3044</rt></ruby>\uff08<ruby>\u4f8b<rt>\u308c\u3044</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306e<ruby>\u554f<rt>\u3082\u3093</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u3068\u3057\u3066<ruby>\u51fa<rt>\u3060</rt></ruby>\u3055\u308c\u3066\u3044\u308b<ruby>\u8a9e<rt>\u3054</rt></ruby><ruby>\u5f59<rt>\u3044</rt></ruby>\u306f\u300c<ruby>\u914d<rt>\u306f\u3044</rt></ruby><ruby>\u9054<rt>\u305f\u3064</rt></ruby>\u300d\uff09\u3092<ruby>\u4f7f<rt>\u3064\u304b</rt></ruby>\u3063\u305f<ruby>\u6587<rt>\u3076\u3093</rt></ruby>\u306b\u306a\u3063\u3066\u3044\u307e\u3059\u3002</span><br><span style=\"color:#1e3a8a;\">Pada <strong>Mondai 5</strong>, keluar <strong>5 soal</strong> yang meminta Anda memilih satu kalimat yang menggunakan sebuah kata dengan benar. Keempat kalimat pilihan seluruhnya menggunakan kosakata yang sedang diujikan pada soal tersebut (pada contoh soal ini, kosakata yang diujikan adalah \u300c\u914d\u9054\u300d / <em>pengantaran</em>).</span></p></div>\n<h3>Latihan 1 \u00b7 Mondai 5: Kata Benda (Hal. Buku 106-107)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu penggunaan kata yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span><strong>\u624b\u6bb5</strong>\uff08\u3057\u3085\u3060\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(cara / sarana / metode)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u304a<ruby>\u8179<rt>\u306a\u304b</rt></ruby>\u304c\u75db\u304f\u306a\u3063\u305f\u3068\u304d\u306f\u3001\u6696\u304b\u3044<u>\u624b\u6bb5</u>\u3092\u3059\u308b\u3068\u3044\u3044\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Saat sakit perut, sebaiknya melakukan cara/sarana yang hangat.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u81ea\u5206\u3067\u4f1a\u793e\u3092\u3064\u304f\u308b\u305f\u3081\u306e<u>\u624b\u6bb5</u>\u306f\u3044\u304f\u3064\u304b\u3042\u308a\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Ada beberapa cara/sarana untuk mendirikan perusahaan sendiri.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u65b0\u3057\u3044\u6642\u8a08\u3092\u8cb7\u3063\u305f<u>\u624b\u6bb5</u>\u306f\u3001\u96fb\u6c60\u3092\u5165\u308c\u3066\u3082\u52d5\u304b\u306a\u304f\u306a\u3063\u3066\u3057\u307e\u3063\u305f\u305f\u3081\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Cara/sarana membeli jam tangan baru adalah karena meski sudah diisi baterai tetap tidak mau bergerak.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u50cd\u304f\u3068\u304d\u306e<u>\u624b\u6bb5</u>\u304c\u304f\u308f\u3057\u304f\u66f8\u3044\u3066\u3042\u308b\u306e\u3067\u3001\u3053\u308c\u306f\u5927\u5207\u306b\u4fdd\u7ba1\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Karena cara/sarana saat bekerja tertulis dengan rinci, tolong simpan ini baik-baik.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><strong><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u6163<rt>\u304b\u3093</rt></ruby></strong>\uff08\u3057\u3085\u3046\u304b\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(kebiasaan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u308f\u305f\u3057\u306e\u5b66\u6821\u306f\u3001<ruby>\u5730<rt>\u3058</rt></ruby><ruby>\u9707<rt>\u3057\u3093</rt></ruby>\u3084\u706b\u4e8b\u304c\u8d77\u304d\u305f\u3068\u304d\u306b<ruby>\u907f<rt>\u3072</rt></ruby><ruby>\u96e3<rt>\u306a\u3093</rt></ruby>\u3067\u304d\u308b\u3088\u3046\u306b<u><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u6163<rt>\u304b\u3093</rt></ruby></u>\u304c\u3042\u308b\u3002</div>\n      <div class=\"q-id-trans\">Sekolah saya memiliki kebiasaan agar siswa bisa mengungsi saat terjadi gempa atau kebakaran.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u4eca\u65e5\u306f\u904b\u52d5\u4f1a\u306e<u><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u6163<rt>\u304b\u3093</rt></ruby></u>\u304c\u3042\u308b\u4e88\u5b9a\u3060\u3063\u305f\u304c\u3001\u96e8\u306e\u305f\u3081\u4e2d\u6b62\u306b\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Hari ini dijadwalkan ada kebiasaan festival olahraga, tetapi dibatalkan karena hujan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5b66\u6821\u306b<ruby>\u9045<rt>\u3061</rt></ruby><ruby>\u523b<rt>\u3053\u304f</rt></ruby>\u3070\u304b\u308a\u3057\u3066\u3044\u308b\u5f1f\u306b\u3001\u65e9\u304f\u8d77\u304d\u308b<u><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u6163<rt>\u304b\u3093</rt></ruby></u>\u3092\u3064\u3051\u308b\u3088\u3046\u306b\u6ce8\u610f\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya menegur adik laki-laki yang selalu terlambat ke sekolah agar membiasakan diri (menanamkan kebiasaan) bangun pagi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u6765\u6708\u72ac\u3092<ruby>\u98fc<rt>\u304b</rt></ruby>\u3046\u306e\u3067\u3001\u308f\u305f\u3057\u306e\u5bb6\u3067\u306f\u72ac\u3092\u6bce\u65e5\u4e8c\u56de<ruby>\u6563<rt>\u3055\u3093</rt></ruby><ruby>\u6b69<rt>\u307d</rt></ruby>\u306b\u9023\u308c\u3066\u884c\u304f\u3068\u3044\u3046<u><ruby>\u7fd2<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u6163<rt>\u304b\u3093</rt></ruby></u>\u3092\u4f5c\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena bulan depan akan memelihara anjing, di keluarga kami dibuat kebiasaan membawa anjing jalan-jalan dua kali sehari.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><strong><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u614b<rt>\u305f\u3044</rt></ruby></strong>\uff08\u3058\u3087\u3046\u305f\u3044\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(keadaan / kondisi)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u6628\u65e5\u304b\u3089\u5b50\u3069\u3082\u306e\u304a<ruby>\u8179<rt>\u306a\u304b</rt></ruby>\u306e<u><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u614b<rt>\u305f\u3044</rt></ruby></u>\u304c\u60aa\u304f\u3001\u3068\u3066\u3082<ruby>\u5fc3<rt>\u3057\u3093</rt></ruby><ruby>\u914d<rt>\u3071\u3044</rt></ruby>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Sejak kemarin kondisi perut anak saya memburuk, sehingga saya sangat khawatir.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u9ad8\u6821\u751f\u306b\u306a\u3063\u3066\u304b\u3089\u3001<ruby>\u606f\u5b50<rt>\u3080\u3059\u3053</rt></ruby>\u306f<ruby>\u6d3e<rt>\u306f</rt></ruby><ruby>\u624b<rt>\u3067</rt></ruby>\u306a<u><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u614b<rt>\u305f\u3044</rt></ruby></u>\u3092\u9078\u3076\u3088\u3046\u306b\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Setelah menjadi siswa SMA, anak laki-laki saya mulai memilih keadaan yang mencolok.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f7c\u5973\u306f<u><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u614b<rt>\u305f\u3044</rt></ruby></u>\u304c<ruby>\u8c4a<rt>\u3086\u305f</rt></ruby>\u304b\u3067\u3001<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u3044\u308b\u3068\u308f\u305f\u3057\u307e\u3067\u660e\u308b\u3044\u6c17\u6301\u3061\u306b\u306a\u308b\u3002</div>\n      <div class=\"q-id-trans\">Dia kaya akan keadaan, dan kalau berada bersamanya, saya pun ikut merasa ceria.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. 20\u4ee3\u306e\u3068\u304d\u306b\u51fa\u6f14\u3057\u305f\u6620\u753b\u3067\u306e<u><ruby>\u72b6<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u614b<rt>\u305f\u3044</rt></ruby></u>\u304c<ruby>\u8a55<rt>\u3072\u3087\u3046</rt></ruby><ruby>\u4fa1<rt>\u304b</rt></ruby>\u3055\u308c\u3001\u5f7c\u5973\u306f\u6709\u540d\u306b\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena keadaan dalam film yang dibintanginya saat berusia 20-an tahun dinilai bagus, ia menjadi terkenal.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><strong><ruby>\u5272<rt>\u308f\u308a</rt></ruby><ruby>\u5408<rt>\u3042\u3044</rt></ruby></strong>\uff08\u308f\u308a\u3042\u3044\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(persentase / rasio / proporsi)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u304c\u591a\u3044\u306e\u3067\u3001\u4f55\u3067\u3082\u4eba\u6570\u5206\u306b<u><ruby>\u5272<rt>\u308f\u308a</rt></ruby><ruby>\u5408<rt>\u3042\u3044</rt></ruby></u>\u3057\u305f\u304c\u3001\u5b50\u3069\u3082\u306e\u3068\u304d\u306f\u305d\u308c\u304c\u3044\u3084\u3060\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena keluarga kami banyak, segala sesuatu dirasio sesuai jumlah orang, tetapi waktu kecil saya tidak suka itu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u3053\u306e\u6d0b\u670d\u3068\u30d0\u30c3\u30b0\u3001\u30bb\u30fc\u30eb\u306730\u30d1\u30fc\u30bb\u30f3\u30c8<u><ruby>\u5272<rt>\u308f\u308a</rt></ruby><ruby>\u5408<rt>\u3042\u3044</rt></ruby></u>\u3067\u8cb7\u3063\u305f\u3093\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Baju dan tas ini saya beli di obral dengan rasio 30 persen.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u8eca\u3084\u5bb6\u306a\u3069\u306e<ruby>\u9ad8<rt>\u3053\u3046</rt></ruby><ruby>\u4fa1<rt>\u304b</rt></ruby>\u306a\u3082\u306e\u3092\u8cb7\u3046\u3068\u304d\u306f\u3001\u4f55\u56de\u304b\u306b<u><ruby>\u5272<rt>\u308f\u308a</rt></ruby><ruby>\u5408<rt>\u3042\u3044</rt></ruby></u>\u3057\u3066\u304a\u91d1\u3092<ruby>\u652f<rt>\u3057</rt></ruby><ruby>\u6255<rt>\u306f\u3089</rt></ruby>\u3046\u3002</div>\n      <div class=\"q-id-trans\">Saat membeli barang mahal seperti mobil atau rumah, uangnya dibayar dengan dirasio beberapa kali.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u53cd\u5bfe\u3059\u308b\u4eba\u306e<u><ruby>\u5272<rt>\u308f\u308a</rt></ruby><ruby>\u5408<rt>\u3042\u3044</rt></ruby></u>\u304c\u591a\u304f\u3001\u65b0\u3057\u3044\u30d3\u30eb\u306e\u5efa\u8a2d\u3092\u4e2d\u6b62\u3059\u308b\u3053\u3068\u306b\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena proporsi/persentase orang yang menentang banyak, pembangunan gedung baru diputuskan untuk dibatalkan.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><strong>\u6b20\u70b9</strong>\uff08\u3051\u3063\u3066\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(kekurangan / kelemahan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5bb6\u3092\u51fa\u305f\u5f8c\u3067<u>\u6b20\u70b9</u>\u306b\u6c17\u3065\u304d\u3001\u3042\u308f\u3066\u3066\u5bb6\u307e\u3067\u53d6\u308a\u306b<ruby>\u623b<rt>\u3082\u3069</rt></ruby>\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Setelah keluar rumah, saya menyadari kekurangan (barang) dan terburu-buru pulang ke rumah untuk mengambilnya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u4ed5\u4e8b\u3067<u>\u6b20\u70b9</u>\u304c\u3042\u3063\u3066\u3001\u3059\u3063\u304b\u308a\u5e30\u308b\u306e\u304c<ruby>\u9045<rt>\u304a\u305d</rt></ruby>\u304f\u306a\u3063\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena ada kekurangan di pekerjaan, kepulangan saya menjadi sangat terlambat.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3053\u306e<ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby><ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u306e<u>\u6b20\u70b9</u>\u306f\u3001\u96fb\u6c60\u304c\u306a\u304f\u306a\u308b\u306e\u304c\u65e9\u3044\u3053\u3068\u3060\u3002</div>\n      <div class=\"q-id-trans\">Kekurangan ponsel ini adalah baterainya cepat habis.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u30ac\u30e9\u30b9\u306e\u30b3\u30c3\u30d7\u3092<ruby>\u5e8a<rt>\u3086\u304b</rt></ruby>\u306b\u843d\u3068\u3057\u3066\u3001\u5e95\u306e\u90e8\u5206\u304c<u>\u6b20\u70b9</u>\u3057\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Gelas kaca jatuh ke lantai dan bagian dasarnya mengalami kekurangan.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><strong><ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u69d8<rt>\u3088\u3046</rt></ruby></strong>\uff08\u3069\u3046\u3088\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(sama seperti / serupa dengan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. 18<ruby>\u6b73<rt>\u3055\u3044</rt></ruby>\u4ee5\u4e0b\u306e\u65b9\u304c<ruby>\u7533<rt>\u3082\u3046</rt></ruby>\u3057<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080\u305f\u3081\u306b\u306f\u3001\u3054<ruby>\u4e21<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u89aa<rt>\u3057\u3093</rt></ruby>\u306e<u><ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u69d8<rt>\u3088\u3046</rt></ruby></u>\u304c\u5fc5\u8981\u306a\u3093\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Agar orang berusia 18 tahun ke bawah dapat mendaftar, diperlukan kesamaan/serupa dari kedua orang tua.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u7d50\u5a5a\u3057\u3066\u304b\u3089\u306f\u3001\u5bb6\u3092\u5efa\u3066\u76f4\u3057\u3066\u3001<ruby>\u59bb<rt>\u3064\u307e</rt></ruby>\u306e<ruby>\u4e21<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u89aa<rt>\u3057\u3093</rt></ruby>\u3068<u><ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u69d8<rt>\u3088\u3046</rt></ruby></u>\u3057\u3066\u3044\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Setelah menikah, kami membangun ulang rumah dan tinggal secara sama/serupa dengan orang tua istri.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u308f\u305f\u3057\u304c\u99c5\u306e\u30db\u30fc\u30e0\u306b<ruby>\u5230<rt>\u3068\u3046</rt></ruby><ruby>\u7740<rt>\u3061\u3083\u304f</rt></ruby>\u3057\u305f\u306e\u3068\u307b\u307c<u><ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u69d8<rt>\u3088\u3046</rt></ruby></u>\u306b\u3001\u96fb\u8eca\u304c\u51fa\u767a\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Hampir sama/serupa dengan tibanya saya di peron stasiun, kereta berangkat.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u59b9\u3068\u308f\u305f\u3057\u306f\u3001<u><ruby>\u540c<rt>\u3069\u3046</rt></ruby><ruby>\u69d8<rt>\u3088\u3046</rt></ruby></u>\u306b\u80b2\u3066\u3089\u308c\u305f\u306e\u306b\u6027\u683c\u304c<ruby>\u5168<rt>\u305c\u3093</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3046\u3002</div>\n      <div class=\"q-id-trans\">Adik perempuan saya dan saya dibesarkan dengan cara yang sama, tetapi sifat kami sama sekali berbeda.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span><strong><ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u6a19<rt>\u3072\u3087\u3046</rt></ruby></strong>\uff08\u3082\u304f\u3072\u3087\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(target / sasaran)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u4e21<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u89aa<rt>\u3057\u3093</rt></ruby>\u306b\u65b0\u3057\u3044\u5bb6\u3092\u30d7\u30ec\u30bc\u30f3\u30c8\u3059\u308b\u3068\u3044\u3046<u><ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u6a19<rt>\u3072\u3087\u3046</rt></ruby></u>\u306e\u305f\u3081\u306b\u8caf\u91d1\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Saya menabung demi target menghadiahkan rumah baru kepada kedua orang tua.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u660e\u65e5\u306f\u3001<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068<ruby>\u4e00<rt>\u3044\u3063</rt></ruby><ruby>\u7dd2<rt>\u3057\u3087</rt></ruby>\u306b\u56f3\u66f8\u9928\u3067\u52c9\u5f37\u3059\u308b<u><ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u6a19<rt>\u3072\u3087\u3046</rt></ruby></u>\u3092\u3057\u3066\u3044\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Besok saya membuat target untuk belajar bersama teman di perpustakaan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u308f\u305f\u3057\u304c\u4ed5\u4e8b\u3092\u3059\u308b<u><ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u6a19<rt>\u3072\u3087\u3046</rt></ruby></u>\u306f\u3001\u304a\u91d1\u306e\u305f\u3081\u3068\u3001<ruby>\u8272<rt>\u3044\u308d</rt></ruby><ruby>\u3005<rt>\u3044\u308d</rt></ruby>\u306a<ruby>\u7d4c<rt>\u3051\u3044</rt></ruby><ruby>\u9a13<rt>\u3051\u3093</rt></ruby>\u3092\u3059\u308b\u305f\u3081\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Target saya bekerja adalah demi uang dan demi mendapatkan berbagai pengalaman.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u540c\u3058\u3088\u3046\u306a<ruby>\u5098<rt>\u304b\u3055</rt></ruby>\u304c\u305f\u304f\u3055\u3093\u3042\u308b\u306e\u3067\u3001\u81ea\u5206\u306e<ruby>\u5098<rt>\u304b\u3055</rt></ruby>\u306b<u><ruby>\u76ee<rt>\u3082\u304f</rt></ruby><ruby>\u6a19<rt>\u3072\u3087\u3046</rt></ruby></u>\u3092\u3064\u3051\u3066\u304a\u3044\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena ada banyak payung yang mirip, saya memasang target pada payung saya sendiri.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span><strong><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6e90<rt>\u3052\u3093</rt></ruby></strong>\uff08\u3057\u3052\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(sumber daya)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u308f\u305f\u3057\u306e\u56fd\u3067\u306f\u3001\u304a\u7c73\u3092<u><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6e90<rt>\u3052\u3093</rt></ruby></u>\u306b\u3057\u3066\u4f5c\u3089\u308c\u305f\u6599\u7406\u304c\u305f\u304f\u3055\u3093\u3042\u308a\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Di negara saya, ada banyak masakan yang dibuat dengan menjadikan beras sebagai sumber daya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u7d19\u306f<u><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6e90<rt>\u3052\u3093</rt></ruby></u>\u3068\u3057\u3066\u4f55\u5ea6\u3067\u3082<ruby>\u5229<rt>\u308a</rt></ruby><ruby>\u7528<rt>\u3088\u3046</rt></ruby>\u3059\u308b\u3053\u3068\u304c\u3067\u304d\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Kertas dapat dimanfaatkan berulang kali sebagai sumber daya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3082\u3057\u6642\u9593\u304c\u3042\u3063\u305f\u3089\u3001\u660e\u65e5\u306e\u304a<ruby>\u5f01<rt>\u3079\u3093</rt></ruby><ruby>\u5f53<rt>\u3068\u3046</rt></ruby>\u306e<u><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6e90<rt>\u3052\u3093</rt></ruby></u>\u3092\u8cb7\u3044\u306b\u884c\u3063\u3066\u304f\u308c\u306a\u3044\uff1f</div>\n      <div class=\"q-id-trans\">Kalau ada waktu, maukah kamu pergi membeli sumber daya untuk bekal makan siang besok?</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u6700\u521d\u306e\u3046\u3061\u306f\u4ed6\u306e\u4eba\u304c\u304b\u3044\u305f\u4f5c\u54c1\u3092<u><ruby>\u8cc7<rt>\u3057</rt></ruby><ruby>\u6e90<rt>\u3052\u3093</rt></ruby></u>\u306b\u3057\u3066\u3001\u7d75\u306e\u7df4\u7fd2\u3092\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Pada awalnya, saya berlatih menggambar dengan menjadikan karya yang digambar orang lain sebagai sumber daya.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><strong>\u611f\u899a</strong>\uff08\u304b\u3093\u304b\u304f\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(sensasi / kepekaan indra / rasa)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5f7c\u306b\u521d\u3081\u3066\u4f1a\u3063\u305f\u3068\u304d\u3001\u3068\u3066\u3082\u3044\u3044<u>\u611f\u899a</u>\u3060\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat pertama kali bertemu dengannya, sensasinya sangat bagus.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u5b66\u6821\u3067\u306f<u>\u611f\u899a</u>\u3092\u5b88\u3063\u3066\u884c\u52d5\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Di sekolah kita harus bertindak dengan mematuhi sensasi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u30cd\u30c3\u30af\u30ec\u30b9\u3092\u4f5c\u308b\u3068\u304d\u306f\u3001\u624b\u5148\u306e<u>\u611f\u899a</u>\u304c\u3068\u3066\u3082\u91cd\u8981\u3060\u3002</div>\n      <div class=\"q-id-trans\">Saat membuat kalung, kepekaan (rasa) ujung jari sangatlah penting.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u4f53\u306e<u>\u611f\u899a</u>\u304c\u60aa\u3044\u306e\u3067\u3001\u4eca\u65e5\u306f\u65e9\u3081\u306b\u5e30\u308a\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Karena sensasi tubuh saya kurang baik, hari ini saya pulang lebih awal.</div>\n    </div>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\uff081 \u304b\u3063\u3053\u3046 [penampilan/pakaian]\u30fb3 \u7406\u7531 [alasan]\u30fb4 \u6761\u4ef6 [syarat]\uff09\u3000\u2461 3\uff081 \u8a13\u7df4 [pelatihan]\u30fb2 \u7df4\u7fd2 [latihan]\u30fb4 \u6c7a\u307e\u308a\u30fb\u30eb\u30fc\u30eb [aturan]\uff09\u3000\u2462 1\uff082 \u670d\u88c5\u30fb\u304b\u3063\u3053\u3046 [pakaian]\u30fb3 \u8868\u60c5 [ekspresi wajah]\u30fb4 \u6f14\u6280 [akting]\uff09\u3000\u2463 4\uff081 \u5206\u3051\u305f [membagi]\u30fb2 \u5272\u5f15 [diskon]\u30fb3 \u5206\u5272\u30fb\u5206\u3051\u3066 [membagi/mencicil]\uff09\u3000\u2464 3\uff081 \u5fd8\u308c\u7269 [barang tertinggal]\u30fb2 \u554f\u984c\u30fb\u30df\u30b9 [masalah/kesalahan]\u30fb4 \u6b20\u3051\u3066 [cuil/retak]\uff09\u3000\u2465 4\uff081 \u540c\u610f [persetujuan]\u30fb2 \u4e00\u7dd2\u306b\u4f4f\u3093\u3067\u30fb\u540c\u5c45 [tinggal bersama]\u30fb3 \u540c\u6642 [bersamaan]\uff09\u3000\u2466 1\uff082 \u7d04\u675f [janji]\u30fb3 \u76ee\u7684 [tujuan]\u30fb4 \u30de\u30fc\u30af [tanda]\uff09\u3000\u2467 2\uff081 \u539f\u6599 [bahan baku]\u30fb3 \u6750\u6599 [bahan]\u30fb4 \u898b\u672c [contoh/sampel]\uff09\u3000\u2468 3\uff081 \u5370\u8c61 [kesan]\u30fb2 \u898f\u5247 [peraturan]\u30fb4 \u5177\u5408 [kondisi]\uff09</div>\n<h3>Latihan 2 \u00b7 Mondai 5: Kata Kerja Golongan III / Kango (Hal. Buku 108-109)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu penggunaan kata yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span><strong>\u691c\u67fb</strong>\uff08\u3051\u3093\u3055\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pemeriksaan / inspeksi)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u304b\u3070\u3093\u306e\u4e2d\u306b\u8ca1\u5e03\u304c\u5165\u3063\u3066\u3044\u308b\u304b\u3069\u3046\u304b<u>\u691c\u67fb</u>\u3057\u3066\u304b\u3089\u5bb6\u3092\u51fa\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya keluar rumah setelah menginspeksi apakah dompet ada di dalam tas atau tidak.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <ruby>\u5bbf<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306f\u6bce\u65e5\u3001\u5148\u751f\u306b\u308f\u305f\u3057\u3066<u>\u691c\u67fb</u>\u3057\u3066\u3082\u3089\u3046\u3002</div>\n      <div class=\"q-id-trans\">PR setiap hari saya serahkan kepada guru untuk diinspeksi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u98db\u884c\u6a5f\u306b\u4e57\u308b<ruby>\u5ba2<rt>\u304d\u3083\u304f</rt></ruby>\u304c\u5371\u306a\u3044\u3082\u306e\u3092\u6301\u3063\u3066\u3044\u306a\u3044\u304b\u3001<ruby>\u8377<rt>\u306b</rt></ruby><ruby>\u7269<rt>\u3082\u3064</rt></ruby>\u3092<u>\u691c\u67fb</u>\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Memeriksa/menginspeksi barang bawaan penumpang pesawat agar tidak membawa benda berbahaya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <ruby>\u9593<rt>\u307e</rt></ruby><ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3048\u305f\u3068\u3053\u308d\u306f\u3001\u8f9e\u66f8\u3092\u4f7f\u3063\u3066<u>\u691c\u67fb</u>\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Bagian yang salah, silakan diinspeksi menggunakan kamus.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><strong>\u6d41\u884c</strong>\uff08\u308a\u3085\u3046\u3053\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(tren / sedang populer)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u30b5\u30c3\u30ab\u30fc\u306f\u30dc\u30fc\u30eb\u304c\u3042\u308c\u3070<ruby>\u904a<rt>\u3042\u305d</rt></ruby>\u3079\u308b\u306e\u3067\u3001\u5b50\u3069\u3082\u306b\u3082\u5927\u4eba\u306b\u3082<u>\u6d41\u884c</u>\u306e\u30b9\u30dd\u30fc\u30c4\u3060\u3002</div>\n      <div class=\"q-id-trans\">Karena sepak bola bisa dimainkan asalkan ada bola, itu adalah olahraga yang menjadi tren bagi anak-anak maupun orang dewasa.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u30af\u30e9\u30b9\u30e1\u30fc\u30c8\u306e<ruby>\u5ddd<rt>\u304b\u308f</rt></ruby><ruby>\u6751<rt>\u3080\u3089</rt></ruby>\u3055\u3093\u306f\u3001\u982d\u304c\u3044\u3044\u3053\u3068\u3067<u>\u6d41\u884c</u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Teman sekelas saya, Saudari Kawamura, sedang tren karena kepintarannya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3053\u306e\u72ac\u306f\u3001\u753a\u306e\u4f4f\u4eba\u307f\u3093\u306a\u306b<u>\u6d41\u884c</u>\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Anjing ini sedang tren di kalangan seluruh penduduk kota.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u3053\u308c\u306f\u300110\u4ee3\u306e\u5b50\u305f\u3061\u306e\u3042\u3044\u3060\u3067<u>\u6d41\u884c</u>\u3057\u3066\u3044\u308b\u30b2\u30fc\u30e0\u3060\u3002</div>\n      <div class=\"q-id-trans\">Ini adalah gim yang sedang menjadi tren di kalangan anak-anak usia belasan tahun.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><strong><ruby>\u8a13<rt>\u304f\u3093</rt></ruby><ruby>\u7df4<rt>\u308c\u3093</rt></ruby></strong>\uff08\u304f\u3093\u308c\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pelatihan / latihan intensif)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u7fd2\u3063\u305f\u3053\u3068\u3092\u5fd8\u308c\u306a\u3044\u3088\u3046\u306b\u3001\u6388\u696d\u306e\u3042\u3068\u306f\u5fc5\u305a<u><ruby>\u8a13<rt>\u304f\u3093</rt></ruby><ruby>\u7df4<rt>\u308c\u3093</rt></ruby></u>\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Agar tidak lupa apa yang telah dipelajari, setelah pelajaran selesai saya selalu melakukan pelatihan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u65e9\u8d77\u304d\u3057\u3066\u30ab\u30d5\u30a7\u306b\u884c\u304d\u3001\u5e30\u3063\u305f\u3089\u8aad\u66f8\u3092\u3059\u308b\u306e\u304c\u6bce\u65e5\u306e<u><ruby>\u8a13<rt>\u304f\u3093</rt></ruby><ruby>\u7df4<rt>\u308c\u3093</rt></ruby></u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Bangun pagi pergi ke kafe, lalu sepulangnya membaca buku adalah pelatihan saya setiap hari.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5b50\u3069\u3082\u306e\u3068\u304d\u3001\u81ea\u5206\u3092\u5b88\u308b\u305f\u3081\u306e<u><ruby>\u8a13<rt>\u304f\u3093</rt></ruby><ruby>\u7df4<rt>\u308c\u3093</rt></ruby></u>\u3068\u3057\u3066<ruby>\u67d4<rt>\u3058\u3085\u3046</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u3092\u7fd2\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Waktu kecil, saya belajar judo sebagai pelatihan untuk melindungi diri sendiri.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u3053\u306e\u756a\u7d44\u3067\u306f\u3001\u82f1\u8a9e\u3092\u4f7f\u3063\u3066\u65e5\u672c\u8a9e\u6587\u6cd5\u306e\u4f7f\u3044\u65b9\u306e<u><ruby>\u8a13<rt>\u304f\u3093</rt></ruby><ruby>\u7df4<rt>\u308c\u3093</rt></ruby></u>\u3092\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Di acara TV ini, mereka melakukan pelatihan cara penggunaan tata bahasa Jepang memakai bahasa Inggris.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><strong><ruby>\u5ba3<rt>\u305b\u3093</rt></ruby><ruby>\u4f1d<rt>\u3067\u3093</rt></ruby></strong>\uff08\u305b\u3093\u3067\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(promosi / iklan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u308f\u304c\u793e\u306e\u65b0\u3057\u3044\u30b5\u30fc\u30d3\u30b9\u304c\u59cb\u307e\u308b\u3053\u3068\u3092\u3001\u52d5\u753b\u3067<u><ruby>\u5ba3<rt>\u305b\u3093</rt></ruby><ruby>\u4f1d<rt>\u3067\u3093</rt></ruby></u>\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Mempromosikan dimulainya layanan baru perusahaan kami melalui video.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u793e\u9577\u304b\u3089\u306e<u><ruby>\u5ba3<rt>\u305b\u3093</rt></ruby><ruby>\u4f1d<rt>\u3067\u3093</rt></ruby></u>\u306f\u3001\u590f\u4f11\u307f\u3068\u3057\u30663\u9031\u9593\u305a\u3064\u4f11\u3093\u3067\u3044\u3044\u3068\u3044\u3046\u8a71\u3060\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Promosi dari direktur adalah pembicaraan bahwa kami boleh mengambil libur musim panas masing-masing 3 minggu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <ruby>\u4e8b<rt>\u3058</rt></ruby><ruby>\u6545<rt>\u3053</rt></ruby>\u304c\u3042\u3063\u3066\u96fb\u8eca\u306e\u767a\u8eca\u6642\u9593\u304c<ruby>\u9045<rt>\u304a\u304f</rt></ruby>\u308c\u3066\u3044\u308b\u3053\u3068\u3092\u3001\u99c5\u54e1\u304c<u><ruby>\u5ba3<rt>\u305b\u3093</rt></ruby><ruby>\u4f1d<rt>\u3067\u3093</rt></ruby></u>\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Petugas stasiun sedang mempromosikan bahwa jadwal keberangkatan kereta terlambat karena ada kecelakaan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u9060\u304f\u306b\u4f4f\u3093\u3067\u3044\u308b\u53cb\u4eba\u306b\u306f\u624b\u7d19\u3092\u66f8\u3044\u3066\u3001\u7d50\u5a5a\u3057\u305f\u3053\u3068\u3092<u><ruby>\u5ba3<rt>\u305b\u3093</rt></ruby><ruby>\u4f1d<rt>\u3067\u3093</rt></ruby></u>\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Kepada teman yang tinggal jauh, saya menulis surat dan mempromosikan bahwa saya sudah menikah.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><strong><ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby></strong>\uff08\u3057\u3093\u305b\u3044\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pengajuan / permohonan resmi)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5e02\u5f79\u6240\u306b\u884c\u3063\u305f\u3089\u3001\u307e\u305a\u306f<u><ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby></u>\u306b\u884c\u304d\u3001\u756a\u53f7\u304c\u66f8\u304b\u308c\u305f\u7d19\u3092\u3082\u3089\u3046\u3002</div>\n      <div class=\"q-id-trans\">Setelah tiba di balai kota, pertama-tama pergi ke pengajuan lalu mengambil kertas bertuliskan nomor.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u30d3\u30b6\u306e<u><ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby></u>\u3092\u3059\u308b\u305f\u3081\u306b\u3001\u5916\u56fd\u4eba\u5411\u3051\u306e\u30cf\u30f3\u30b3\u3092\u4f5c\u308a\u307e\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Untuk melakukan pengajuan visa, saya membuat stempel (hanko) khusus orang asing.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u53cb\u4eba\u306e\u7d50\u5a5a\u5f0f\u306e<u><ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby></u>\u304c\u306f\u304c\u304d\u3067<ruby>\u5c4a<rt>\u3068\u3069</rt></ruby>\u3044\u305f\u3002</div>\n      <div class=\"q-id-trans\">Pengajuan pesta pernikahan teman tiba dalam bentuk kartu pos.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u500b\u4eba\u3067\u4f1a\u793e\u3092\u4f5c\u308b\u305f\u3081\u306b\u3001\u4e00\u5e74\u5206\u306e\u884c\u52d5\u306e<u><ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby></u><ruby>\u66f8<rt>\u3057\u3087</rt></ruby>\u3092\u66f8\u3044\u305f\u3002</div>\n      <div class=\"q-id-trans\">Untuk mendirikan perusahaan perseorangan, saya menulis surat pengajuan kegiatan selama satu tahun.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><strong><ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby></strong>\uff08\u3053\u3046\u304b\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menukar / mengganti)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u5c31<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u8077<rt>\u3057\u3087\u304f</rt></ruby><ruby>\u5148<rt>\u3055\u304d</rt></ruby>\u306e\u4f1a\u793e\u306f\u3068\u306a\u308a\u306e\u770c\u306b\u3042\u308b\u306e\u3067\u3001\u5bb6\u3092<u><ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby></u>\u3057\u306a\u3051\u308c\u3070\u306a\u3089\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Karena perusahaan tempat bekerja berada di prefektur sebelah, saya harus menukar rumah.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u521d\u3081\u3066\u751f\u307e\u308c\u308b\u5b50\u3069\u3082\u306e\u305f\u3081\u306b\u3001\u6d0b\u670d\u3084\u751f\u6d3b\u7528\u54c1\u3092<u><ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby></u>\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Demi anak yang lahir untuk pertama kalinya, kami menukar pakaian dan perlengkapan rumah tangga.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u51ac\u306b\u306a\u3063\u3066\u305f\u304f\u3055\u3093\u306e<ruby>\u96ea<rt>\u3086\u304d</rt></ruby>\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u308b\u524d\u306b\u3001\u30bf\u30a4\u30e4\u3092<u><ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby></u>\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Sebelum musim dingin datang dan banyak salju turun, kami mengganti/menukar ban.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <ruby>\u5409<rt>\u3088\u3057</rt></ruby><ruby>\u5ca1<rt>\u304a\u304b</rt></ruby>\u5148\u751f\u304c\u304a\u4f11\u307f\u3055\u308c\u308b\u306e\u3067\u30013\u6708\u307e\u3067\u306f\u308f\u305f\u3057\u304c\u3053\u306e\u30af\u30e9\u30b9\u3092<u><ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u63db<rt>\u304b\u3093</rt></ruby></u>\u3057\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Karena Ibu Guru Yoshioka sedang cuti, sampai bulan Maret saya yang menukar kelas ini.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span><strong><ruby>\u5f71<rt>\u3048\u3044</rt></ruby><ruby>\u97ff<rt>\u304d\u3087\u3046</rt></ruby></strong>\uff08\u3048\u3044\u304d\u3087\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pengaruh)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5e83\u3044<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u3067\u5927\u304d\u3044\u58f0\u3092\u51fa\u3059\u3068\u3001\u58f0\u304c\u3088\u304f<u><ruby>\u5f71<rt>\u3048\u3044</rt></ruby><ruby>\u97ff<rt>\u304d\u3087\u3046</rt></ruby></u>\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Kalau mengeluarkan suara keras di kamar yang luas, suaranya sangat berpengaruh.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <ruby>\u75b2<rt>\u3064\u304b</rt></ruby>\u308c\u3066\u3044\u308b\u3088\u3046\u3059\u306e<ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u306b\u4f11\u3093\u3067\u307b\u3057\u304f\u3066\u3001\u65c5\u884c\u306b\u884c\u3053\u3046\u3068<u><ruby>\u5f71<rt>\u3048\u3044</rt></ruby><ruby>\u97ff<rt>\u304d\u3087\u3046</rt></ruby></u>\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena ingin keluarga yang tampak lelah beristirahat, saya memengaruhi mereka untuk pergi berlibur.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f7c\u306e\u30d4\u30a2\u30ce\u306e<u><ruby>\u5f71<rt>\u3048\u3044</rt></ruby><ruby>\u97ff<rt>\u304d\u3087\u3046</rt></ruby></u>\u304c<ruby>\u7d20<rt>\u3059</rt></ruby><ruby>\u6674<rt>\u3070</rt></ruby>\u3089\u3057\u3044\u306e\u3067\u3001\u611f\u52d5\u3057\u3066\u6ce3\u3044\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena pengaruh permainan pianonya luar biasa, saya terharu hingga menangis.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5927\u597d\u304d\u306a\u6b4c\u624b\u306e<u><ruby>\u5f71<rt>\u3048\u3044</rt></ruby><ruby>\u97ff<rt>\u304d\u3087\u3046</rt></ruby></u>\u3092\u53d7\u3051\u3066\u3001\u9ad8\u6821\u751f\u306e\u3068\u304d\u306b\u521d\u3081\u3066\u30ae\u30bf\u30fc\u3092\u8cb7\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena mendapat pengaruh dari penyanyi favorit, saya membeli gitar pertama kali saat SMA.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span><strong><ruby>\u7e2e<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby></strong>\uff08\u3057\u3085\u304f\u3057\u3087\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pengecilan / penyusutan skala)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u660e\u308b\u304b\u3063\u305f\u7a7a\u304c<u><ruby>\u7e2e<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby></u>\u3057\u3066\u3001\u307d\u3064\u307d\u3064\u3068\u96e8\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u3063\u3066\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Langit yang tadinya cerah menyusut/mengecil, lalu hujan mulai turun rintik-rintik.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u6765\u5e74\u304b\u3089\u306f\u4f1a\u793e\u3092<u><ruby>\u7e2e<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby></u>\u3057\u3066\u3001\u6570\u540d\u306e\u793e\u54e1\u3060\u3051\u3067\u50cd\u304f\u3053\u3068\u306b\u6c7a\u3081\u305f\u3002</div>\n      <div class=\"q-id-trans\">Mulai tahun depan, kami memutuskan untuk memperkecil/menyusutkan skala perusahaan dan bekerja hanya dengan beberapa karyawan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u4f53\u91cd\u3092\u843d\u3068\u3057\u3066\u3001\u4f53\u304c\u3060\u3044\u3076<u><ruby>\u7e2e<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby></u>\u3057\u305f\u306e\u3067\u3001\u65b0\u3057\u3044\u670d\u3092\u8cb7\u3046\u5fc5\u8981\u304c\u3042\u308b\u3002</div>\n      <div class=\"q-id-trans\">Karena menurunkan berat badan dan tubuh saya cukup menyusut/mengecil, saya perlu membeli baju baru.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u304a\u91d1\u304c\u306a\u3044\u4eba\u304c<ruby>\u5897<rt>\u3075</rt></ruby>\u3048\u3001\u8eca\u3084\u81ea\u5206\u306e\u5bb6\u3092\u8cb7\u3046\u4eba\u306f<u><ruby>\u7e2e<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u5c0f<rt>\u3057\u3087\u3046</rt></ruby></u>\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Orang yang tidak punya uang bertambah, dan orang yang membeli mobil atau rumah sendiri menyusut/mengecil.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><strong>\u5165\u529b</strong>\uff08\u306b\u3085\u3046\u308a\u3087\u304f\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(input / memasukkan (data/karakter))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u65e5\u672c\u3067\u8cb7\u3063\u305f\u30d1\u30bd\u30b3\u30f3\u3067\u3001<ruby>\u4e2d<rt>\u3061\u3085\u3046</rt></ruby><ruby>\u56fd<rt>\u3054\u304f</rt></ruby><ruby>\u8a9e<rt>\u3054</rt></ruby>\u3092<u>\u5165\u529b</u>\u3067\u304d\u308b\u3088\u3046\u306b\u30bb\u30c3\u30c8\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya mengatur komputer yang dibeli di Jepang agar dapat menginput bahasa Mandarin.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u76ee\u306b\u60aa\u3044\u304b\u3089\u3001\u96fb\u6c17\u3092<u>\u5165\u529b</u>\u3057\u3066\u52c9\u5f37\u3057\u305f\u307b\u3046\u304c\u3044\u3044\u3088\u3002</div>\n      <div class=\"q-id-trans\">Karena tidak baik untuk mata, sebaiknya belajar dengan menginput lampu/listrik.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u305f\u304f\u3055\u3093\u679c\u7269\u3092\u98df\u3079\u3066\u3001\u30d3\u30bf\u30df\u30f3\u3092<u>\u5165\u529b</u>\u3059\u308b\u3088\u3046\u306b\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Saya berusaha banyak makan buah agar menginput vitamin.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby><ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u306e\u96fb\u6c60\u304c\u5168\u90e8\u306a\u304f\u306a\u3063\u3066\u304b\u3089\u3001<u>\u5165\u529b</u>\u3057\u305f\u65b9\u304c\u3044\u3044\u3067\u3059\u3088\u3002</div>\n      <div class=\"q-id-trans\">Sebaiknya melakukan input setelah baterai ponsel benar-benar habis seluruhnya.</div>\n    </div>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\uff081 \u78ba\u8a8d [memastikan]\u30fb2 \u78ba\u8a8d [memeriksa]\u30fb4 \u8abf\u3079\u3066 [mengecek/mencari]\uff09\u3000\u2461 4\uff081 \u4eba\u6c17 [populer]\u30fb2 \u6709\u540d [terkenal]\u30fb3 \u611b\u3055\u308c\u3066 [disayangi]\uff09\u3000\u2462 3\uff081 \u5fa9\u7fd2 [mengulang pelajaran]\u30fb2 \u7fd2\u6163 [kebiasaan]\u30fb4 \u89e3\u8aac [penjelasan]\uff09\u3000\u2463 1\uff082 \u767a\u8868 [pengumuman]\u30fb3 \u653e\u9001\u30fb\u30a2\u30ca\u30a6\u30f3\u30b9 [siaran/pengumuman]\u30fb4 \u5831\u544a [kabar/laporan]\uff09\u3000\u2464 2\uff081 \u53d7\u4ed8 [resepsionis]\u30fb3 \u6848\u5185 [undangan/pemberitahuan]\u30fb4 \u8a08\u753b [rencana]\uff09\u3000\u2465 3\uff081 \u5f15\u3063\u8d8a\u3055 [pindah rumah]\u30fb2 \u7528\u610f\u30fb\u6e96\u5099 [menyiapkan]\u30fb4 \u62c5\u4efb [mengajar/menangani kelas]\uff09\u3000\u2466 4\uff081 \u97ff\u304f [menggema]\u30fb2 \u63d0\u6848 [mengusulkan]\u30fb3 \u6f14\u594f [permainan musik]\uff09\u3000\u2467 2\uff081 \u6697\u304f\u306a\u3063\u3066 [menjadi gelap]\u30fb3 \u3084\u305b\u305f\u30fb\u7d30\u304f\u306a\u3063\u305f [menjadi kurus/ramping]\u30fb4 \u6e1b\u3063\u3066\u3044\u308b [berkurang]\uff09\u3000\u2468 1\uff082 \u3064\u3051\u3066 [menyalakan]\u30fb3 \u3068\u308b\u30fb\u6442\u53d6\u3059\u308b [mengonsumsi/mengambil asupan]\u30fb4 \u5145\u96fb [mengisi daya]\uff09</div>\n<h3>Latihan 3 \u00b7 Mondai 5: Kata Kerja Dasar / Wago (Hal. Buku 110-111)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu penggunaan kata yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span><strong>\u3042\u304d\u3089\u3081\u308b</strong> <small style=\"color:#1b5e20; font-weight:600;\">(menyerah / berputus asa / merelakan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u3082\u3057\u96e8\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u3063\u305f\u5834\u5408\u306f\u3001\u6765\u9031\u306b<u>\u3042\u304d\u3089\u3081\u307e\u3059</u>\u3002</div>\n      <div class=\"q-id-trans\">Jika hujan turun, kami akan menyerah ke minggu depan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u307b\u304b\u306e\u4f1a\u793e\u3067\u306e<ruby>\u5c31<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u8077<rt>\u3057\u3087\u304f</rt></ruby>\u304c\u6c7a\u307e\u3063\u305f\u306e\u3067\u3001\u4e00\u304b\u6708\u5f8c\u306b\u3053\u3053\u3092<u>\u3042\u304d\u3089\u3081\u307e\u3059</u>\u3002</div>\n      <div class=\"q-id-trans\">Karena sudah diterima bekerja di perusahaan lain, sebulan lagi saya akan menyerah dari tempat ini.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5177\u5408\u304c\u60aa\u3044\u306e\u3067\u3001\u65e9\u3081\u306b<u>\u3042\u304d\u3089\u3081\u3066</u>\u3082\u3044\u3044\u3067\u3057\u3087\u3046\u304b\u3002</div>\n      <div class=\"q-id-trans\">Karena kondisi badan kurang baik, bolehkah saya menyerah lebih awal?</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u4f55\u6642\u9593\u63a2\u3057\u3066\u3082\u898b\u3064\u304b\u3089\u306a\u3044\u3057\u3001\u3082\u3046<u>\u3042\u304d\u3089\u3081\u307e\u3057\u3087\u3046</u>\u3002</div>\n      <div class=\"q-id-trans\">Meskipun mencari berjam-jam tetap tidak ketemu, mari kita menyerah saja.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><strong><ruby>\u983c<rt>\u305f\u3088</rt></ruby>\u308b</strong>\uff08\u305f\u3088\u308b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(mengandalkan / bergantung pada)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u65c5\u884c\u3067\u7559\u5b88\u306b\u3059\u308b\u9593\u3001<ruby>\u98fc<rt>\u304b</rt></ruby>\u3063\u3066\u3044\u308b\u72ac\u3092\u53cb\u4eba\u306b<u><ruby>\u983c<rt>\u305f\u3088</rt></ruby>\u3063\u3066</u>\u3082\u3089\u3046\u3002</div>\n      <div class=\"q-id-trans\">Selama bepergian dan rumah kosong, saya meminta teman mengandalkan anjing peliharaan saya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u5f7c\u306f\u4ed5\u4e8b\u304c\u3042\u307e\u308a\u3067\u304d\u306a\u3044\u306e\u3067\u3001\u3044\u3064\u3082\u4eba\u306b<u><ruby>\u983c<rt>\u305f\u3088</rt></ruby>\u3063\u3066</u>\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Karena dia kurang bisa bekerja, dia selalu mengandalkan orang lain.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u9ad8\u3044\u3068\u3053\u308d\u306b\u767b\u3063\u3066<ruby>\u964d<rt>\u304a</rt></ruby>\u308a\u3089\u308c\u306a\u304f\u306a\u3063\u305f\u3068\u304d\u306f\u5144\u304c<u><ruby>\u983c<rt>\u305f\u3088</rt></ruby>\u3063\u3066</u>\u304f\u308c\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat memanjat tempat tinggi dan tidak bisa turun, kakak laki-laki saya telah mengandalkan saya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u91cd\u3044<ruby>\u8377<rt>\u306b</rt></ruby><ruby>\u7269<rt>\u3082\u3064</rt></ruby>\u3092\u6301\u3063\u3066<ruby>\u968e<rt>\u304b\u3044</rt></ruby><ruby>\u6bb5<rt>\u3060\u3093</rt></ruby>\u3092\u4e0a\u3063\u3066\u3044\u308b\u3068\u3001\u8fd1\u304f\u306b\u3044\u305f\u4eba\u304c<u><ruby>\u983c<rt>\u305f\u3088</rt></ruby>\u3063\u3066</u>\u304f\u308c\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat naik tangga sambil membawa barang berat, orang di dekat situ mengandalkan saya.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><strong>\u56f0\u308b</strong>\uff08\u3053\u307e\u308b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(bingung / kerepotan / kesulitan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u521d\u3081\u3066<ruby>\u8a2a<rt>\u307b\u3046</rt></ruby><ruby>\u554f<rt>\u3082\u3093</rt></ruby>\u3059\u308b\u571f\u5730\u3067\u306f\u3001\u5730\u56f3\u3092\u898b\u3066\u3082\u9053\u306b<u>\u56f0\u3063\u3066</u>\u3057\u307e\u3046\u3002</div>\n      <div class=\"q-id-trans\">Di tempat yang baru pertama kali dikunjungi, meski melihat peta pun tetap bingung pada jalan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. 30\u5206\u304f\u3089\u3044<ruby>\u9045<rt>\u304a\u304f</rt></ruby>\u308c\u3066\u3082\u554f\u984c\u3042\u308a\u307e\u305b\u3093\u304b\u3089\u3001<u>\u56f0\u3089\u306a\u3044\u3067</u>\u6765\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Terlambat sekitar 30 menit tidak masalah kok, jadi datanglah tanpa bingung.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5927\u91cf\u306e\u9ce5\u306b\u8ffd\u3044\u304b\u3051\u3089\u308c\u308b\u3068\u3044\u3046\u6620\u753b\u3092\u307f\u3066\u3001<u>\u56f0\u3063\u3066</u>\u6ce3\u3044\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Menonton film tentang dikejar sekawanan besar burung, saya bingung lalu menangis.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u4f55\u56de\u4f5c\u308a\u76f4\u3057\u3066\u3082\u30a4\u30e1\u30fc\u30b8\u3057\u305f\u3082\u306e\u3068<ruby>\u9055<rt>\u3061\u304c</rt></ruby>\u3046\u5f62\u306b\u306a\u3063\u3066\u3057\u307e\u3044\u3001<u>\u56f0\u3063\u3066</u>\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Meskipun dibuat ulang berkali-kali tetap menjadi bentuk yang berbeda dari yang dibayangkan, sehingga saya bingung/kesulitan.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><strong>\u9006\u3089\u3046</strong>\uff08\u3055\u304b\u3089\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menentang / membantah / melawan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u7236<rt>\u3075</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u306b\u306f\u6700\u5f8c\u307e\u3067<u>\u9006\u3089\u308f\u308c\u3066</u>\u3044\u305f\u304c\u3001\u304a\u91d1\u3092\u8caf\u3081\u3066\u7559\u5b66\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Meskipun sampai akhir ditentang oleh kakek-nenek, saya menabung uang lalu kuliah ke luar negeri.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306e\u610f\u898b\u3092<u>\u9006\u3089\u3063\u305f</u>\u3053\u3068\u3067\u3001\u8a00\u3044\u5408\u3044\u306b\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena menentang pendapat teman, terjadi pertengkaran mulut.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f7c\u306f\u793e\u9577\u306e\u6c7a\u5b9a\u306b<u>\u9006\u3089\u3063\u305f</u>\u3053\u3068\u3067\u3001\u4f1a\u793e\u3092\u8f9e\u3081\u3055\u305b\u3089\u308c\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena dia menentang keputusan direktur, dia diberhentikan dari perusahaan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5f7c\u306e\u8a71\u306f\u5927\u4f53\u3046\u305d\u3060\u304b\u3089\u3001<u>\u9006\u3089\u3063\u305f</u>\u65b9\u304c\u3044\u3044\u3067\u3059\u3088\u3002</div>\n      <div class=\"q-id-trans\">Karena cerita dia kebanyakan bohong, sebaiknya menentangnya saja.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><strong><ruby>\u632f<rt>\u3075</rt></ruby>\u308b</strong>\uff08\u3075\u308b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(melambaikan / mengayunkan / menggoyang)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5375\u3092\u5bb9\u5668\u306b\u5165\u308c\u3066<ruby>\u7bb8<rt>\u306f\u3057</rt></ruby>\u3067\u3088\u304f<u><ruby>\u632f<rt>\u3075</rt></ruby>\u3063\u305f</u>\u3042\u3068\u3001\u725b\u4e73\u3068\u6c34\u3092<ruby>\u52a0<rt>\u304f\u308f</rt></ruby>\u3048\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Setelah memasukkan telur ke wadah dan menggoyangnya baik-baik dengan sumpit, tambahkan susu dan air.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u751f\u307e\u308c\u305f\u3070\u304b\u308a\u306e<ruby>\u606f\u5b50<rt>\u3080\u3059\u3053</rt></ruby>\u3092\u3001<ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u7236<rt>\u3075</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u306b<u><ruby>\u632f<rt>\u3075</rt></ruby>\u3063\u3066</u>\u3082\u3089\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya meminta kakek-nenek menggoyang/melambaikan anak laki-laki saya yang baru lahir.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3042\u305d\u3053\u3067\u5927\u304d\u304f\u624b\u3092<u><ruby>\u632f<rt>\u3075</rt></ruby>\u3063\u3066</u>\u3044\u308b\u306e\u304c\u3001\u308f\u305f\u3057\u306e\u5144\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Orang yang sedang melambaikan tangan dengan lebar di sana adalah kakak laki-laki saya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u304a<ruby>\u5ba2<rt>\u304d\u3083\u304f</rt></ruby>\u3055\u307e\u306b\u306f\u3001\u982d\u3092\u6df1\u304f<u><ruby>\u632f<rt>\u3075</rt></ruby>\u3063\u3066</u>\u3042\u3044\u3055\u3064\u3092\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Kepada pelanggan, silakan menyapa dengan melambaikan/menggoyangkan kepala dalam-dalam.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><strong><ruby>\u9810<rt>\u3042\u305a</rt></ruby>\u3051\u308b</strong>\uff08\u3042\u305a\u3051\u308b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menitipkan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u56f3\u66f8\u9928\u3067\u306f\u4e8c\u9031\u9593\u306710\u518a\u307e\u3067\u306e\u672c\u3092<u><ruby>\u9810<rt>\u3042\u305a</rt></ruby>\u3051\u308b</u>\u3053\u3068\u304c\u3067\u304d\u308b\u3002</div>\n      <div class=\"q-id-trans\">Di perpustakaan dapat menitipkan hingga 10 buku selama dua minggu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u604b\u4eba\u306e<ruby>\u8a95<rt>\u305f\u3093</rt></ruby><ruby>\u751f<rt>\u3058\u3087\u3046</rt></ruby><ruby>\u65e5<rt>\u3073</rt></ruby>\u306b\u3001\u5f7c\u5973\u304c\u597d\u304d\u306a\u82b1\u3068\u30a2\u30af\u30bb\u30b5\u30ea\u30fc\u3092<u><ruby>\u9810<rt>\u3042\u305a</rt></ruby>\u3051\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Pada hari ulang tahun pacar, saya menitipkan bunga dan aksesori yang disukainya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u4ee5\u524d\u304b\u3089\u3084\u3063\u3066\u307f\u305f\u304b\u3063\u305f\u30b2\u30fc\u30e0\u3092\u3001\u53cb\u4eba\u306b<u><ruby>\u9810<rt>\u3042\u305a</rt></ruby>\u3051\u3066</u>\u3082\u3089\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya meminta teman menitipkan gim yang sejak dulu ingin saya coba.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u3086\u3063\u304f\u308a\u3068\u89b3\u5149\u3057\u305f\u3044\u306e\u3067\u3001<ruby>\u8377<rt>\u306b</rt></ruby><ruby>\u7269<rt>\u3082\u3064</rt></ruby>\u3092\u30db\u30c6\u30eb\u306b<u><ruby>\u9810<rt>\u3042\u305a</rt></ruby>\u3051\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Karena ingin berwisata dengan santai, saya menitipkan barang bawaan di hotel.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span><strong>\u305f\u307e\u308b</strong> <small style=\"color:#1b5e20; font-weight:600;\">(menumpuk / terkumpul)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u52c9\u5f37\u3057\u3066\u3044\u308b\u3068\u3001\u3044\u304d\u306a\u308a<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u306b<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304c<u>\u305f\u307e\u3063\u3066</u>\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat sedang belajar, tiba-tiba kucing menumpuk masuk ke kamar.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u5b9f\u5bb6\u306e\u62bc\u5165\u308c\u306b\u306f\u3001\u7740\u308b\u3053\u3068\u304c\u3067\u304d\u306a\u304f\u306a\u3063\u305f\u670d\u304c<u>\u305f\u307e\u3063\u3066</u>\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Di lemari dinding rumah orang tua, menumpuk pakaian yang sudah tidak bisa dipakai lagi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u6691\u3044<ruby>\u5b63<rt>\u304d</rt></ruby><ruby>\u7bc0<rt>\u305b\u3064</rt></ruby>\u306b\u306a\u308b\u3068\u3001\u3053\u306e\u6d77\u306b\u306f\u6bce\u5e74\u305f\u304f\u3055\u3093\u306e\u304a<ruby>\u5ba2<rt>\u304d\u3083\u304f</rt></ruby>\u3055\u3093\u304c<u>\u305f\u307e\u308b</u>\u3002</div>\n      <div class=\"q-id-trans\">Saat musim panas tiba, di pantai ini setiap tahun banyak tamu yang menumpuk.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5b50\u3069\u3082\u305f\u3061\u304c\u6a2a\u65ad\u6b69\u9053\u3092<ruby>\u6e21<rt>\u308f\u305f</rt></ruby>\u308d\u3046\u3068\u3057\u3066\u3044\u308b\u306e\u306b\u3001\u3042\u306e\u8eca\u306f\u8d64\u4fe1\u53f7\u306b\u306a\u3063\u3066\u3082<u>\u305f\u307e\u3089\u306a\u304b\u3063\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Padahal anak-anak hendak menyeberang di zebra cross, mobil itu tetap tidak menumpuk meski lampu sudah merah.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span><strong>\u5411\u304b\u3046</strong>\uff08\u3080\u304b\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menuju / mengarah ke)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u4e8c<ruby>\u6b73<rt>\u3055\u3044</rt></ruby>\u306e\u5a18\u306f\u3001\u7dda\u8def\u306e\u4e0a\u3092\u96fb\u8eca\u304c<u>\u5411\u304b\u3046</u>\u306e\u3092\u898b\u308b\u306e\u304c\u597d\u304d\u3089\u3057\u3044\u3002</div>\n      <div class=\"q-id-trans\">Putri saya yang berumur dua tahun tampaknya suka melihat kereta menuju di atas rel.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u6025\u306b\u5f37\u3044\u98a8\u304c<ruby>\u5439<rt>\u3075</rt></ruby>\u3044\u3066\u304d\u3066\u3001<ruby>\u88ab<rt>\u304b\u3076</rt></ruby>\u3063\u3066\u3044\u305f<ruby>\u5e3d<rt>\u307c\u3046</rt></ruby><ruby>\u5b50<rt>\u3057</rt></ruby>\u304c<u>\u5411\u304b\u3063\u3066</u>\u3044\u3063\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Tiba-tiba angin kencang bertiup, lalu topi yang saya pakai pergi menuju.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <ruby>\u6a2a<rt>\u304a\u3046</rt></ruby><ruby>\u65ad<rt>\u3060\u3093</rt></ruby><ruby>\u6b69<rt>\u307b</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u3092<u>\u5411\u304b\u3046</u>\u3068\u304d\u306f\u3001<ruby>\u5468<rt>\u307e\u308f</rt></ruby>\u308a\u306e\u8eca\u306e\u52d5\u304d\u306b\u3088\u304f\u6ce8\u610f\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Saat menuju zebra cross, harap perhatikan baik-baik pergerakan mobil di sekitar.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u9752\u4fe1\u53f7\u306b\u306a\u308b\u306e\u3092\u5f85\u3063\u3066\u3044\u305f\u3089\u3001\u5927\u304d\u3044\u8eca\u304c\u3053\u3061\u3089\u306b<u>\u5411\u304b\u3063\u3066</u>\u304d\u3066<ruby>\u9a5a<rt>\u304a\u3069\u308d</rt></ruby>\u3044\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat sedang menunggu lampu menjadi hijau, ada mobil besar yang melaju mengarah ke sini sehingga saya kaget.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><strong><ruby>\u6c88<rt>\u3057\u305a</rt></ruby>\u3080</strong>\uff08\u3057\u305a\u3080\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(tenggelam / terbenam)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5c0f\u5b66\u751f\u306e\u3068\u304d\u306f\u3001\u9577\u305525m\u306e\u30d7\u30fc\u30eb\u3092\u6700\u5f8c\u307e\u3067<u><ruby>\u6c88<rt>\u3057\u305a</rt></ruby>\u3080</u>\u3053\u3068\u304c\u3067\u304d\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Waktu SD, saya tidak bisa tenggelam sampai akhir di kolam renang sepanjang 25 m.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u6025\u3044\u3067\u6599\u7406\u3092\u3057\u3066\u3044\u305f\u3089\u3001\u5375\u304c<ruby>\u5e8a<rt>\u3086\u304b</rt></ruby>\u306b<u><ruby>\u6c88<rt>\u3057\u305a</rt></ruby>\u3093\u3067</u><ruby>\u5272<rt>\u308f</rt></ruby>\u308c\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena terburu-buru memasak, telur tenggelam ke lantai lalu pecah.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3053\u306e\u5742\u9053\u3092<u><ruby>\u6c88<rt>\u3057\u305a</rt></ruby>\u3093\u3060</u>\u3042\u3068\u53f3\u306b\u66f2\u304c\u308b\u3068\u3001\u753a\u306e\u56f3\u66f8\u9928\u304c\u3042\u308a\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Setelah tenggelam menuruni jalan tanjakan ini lalu belok kanan, ada perpustakaan kota.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u6d77\u5cb8\u3067\u3001\u592a\u967d\u304c\u6d77\u306b<u><ruby>\u6c88<rt>\u3057\u305a</rt></ruby>\u3093\u3067</u>\u3044\u304f\u3068\u3053\u308d\u3092\u898b\u3066\u3044\u305f\u3044\u3002</div>\n      <div class=\"q-id-trans\">Di pantai, saya ingin terus memandangi matahari yang terbenam ke laut.</div>\n    </div>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 4\uff081 \u5ef6\u671f\u3057\u307e\u3059 [menunda]\u30fb2 \u8f9e\u3081\u307e\u3059 [berhenti/keluar]\u30fb3 \u5e30\u5b85\u3057\u3066 [pulang ke rumah]\uff09\u3000\u2461 2\uff081 \u9810\u304b\u3063\u3066 [menjaga titipan]\u30fb3 \u52a9\u3051\u3066 [menolong]\u30fb4 \u624b\u4f1d\u3063\u3066 [membantu]\uff09\u3000\u2462 4\uff081 \u8ff7\u3063\u3066 [tersesat]\u30fb2 \u7126\u3089\u306a\u3044\u3067 [jangan panik]\u30fb3 \u3053\u308f\u304f\u3066 [takut]\uff09\u3000\u2463 3\uff081 \u53cd\u5bfe\u3055\u308c\u3066 [ditentang]\u30fb2 \u5426\u5b9a\u3057\u305f [menyangkal]\u30fb4 \u805e\u304b\u306a\u3044 [tidak mendengarkan]\uff09\u3000\u2464 3\uff081 \u6df7\u305c\u305f [mengaduk]\u30fb2 \u62b1\u3044\u3066 [menggendong]\u30fb4 \u4e0b\u3052\u3066 [menundukkan]\uff09\u3000\u2465 4\uff081 \u501f\u308a\u308b [meminjam]\u30fb2 \u8d08\u3063\u305f [menghadiahkan]\u30fb3 \u8cb8\u3057\u3066 [meminjamkan]\uff09\u3000\u2466 2\uff081 \u5165\u3063\u3066 [masuk]\u30fb3 \u96c6\u307e\u308b [berkumpul]\u30fb4 \u6b62\u307e\u3089\u306a\u304b\u3063\u305f [tidak berhenti]\uff09\u3000\u2467 4\uff081 \u8d70\u308b [melaju]\u30fb2 \u98db\u3093\u3067 [terbang]\u30fb3 \u6e21\u308b [menyeberang]\uff09\u3000\u2468 4\uff081 \u6cf3\u3050 [berenang]\u30fb2 \u843d\u3061\u3066 [jatuh]\u30fb3 \u4e0b\u3063\u305f [menuruni]\uff09</div>\n<h3>Latihan 4 \u00b7 Mondai 5: Kata Kerja Majemuk (Hal. Buku 112-113)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu penggunaan kata yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span><strong>\u5f85\u3061\u5408\u308f\u305b\u308b</strong>\uff08\u307e\u3061\u3042\u308f\u305b\u308b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(bertemu di tempat yang dijanjikan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u99c5\u524d\u3067<u>\u5f85\u3061\u5408\u308f\u305b\u308b</u>\u3053\u3068\u306b\u306a\u3063\u3066\u3044\u305f\u304c\u3001\u4e00\u6642\u9593\u5f85\u3063\u3066\u3082\u5f7c\u306f\u6765\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Seharusnya bertemu janji di depan stasiun, tetapi setelah menunggu satu jam dia tidak datang.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. 16\u6642\u306b<ruby>\u8377<rt>\u306b</rt></ruby><ruby>\u7269<rt>\u3082\u3064</rt></ruby>\u3092<ruby>\u914d<rt>\u306f\u3044</rt></ruby><ruby>\u9054<rt>\u305f\u3064</rt></ruby>\u3057\u3066\u3082\u3089\u3048\u308b\u3088\u3046\u304a\u9858\u3044\u3057\u305f\u306e\u3067\u3001\u5bb6\u3067<u>\u5f85\u3061\u5408\u308f\u305b\u308b</u>\u3002</div>\n      <div class=\"q-id-trans\">Karena saya sudah minta agar paket diantar jam 16.00, saya bertemu janji di rumah.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u6025\u3044\u3067\u51fa\u767a\u306e\u6e96\u5099\u3092\u3059\u308b\u306e\u3067\u3001\u3082\u3046\u5c11\u3057<u>\u5f85\u3061\u5408\u308f\u305b\u3066</u>\u3082\u3089\u3048\u307e\u3059\u304b\u3002</div>\n      <div class=\"q-id-trans\">Karena saya akan segera bersiap berangkat, bisakah Anda bertemu janji sebentar lagi?</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u7d04\u675f\u306e\u6642\u9593\u304b\u3089\u4e00\u6642\u9593\u3082<u>\u5f85\u3061\u5408\u308f\u305b\u3066</u>\u3044\u308b\u306e\u306b\u3001<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306f\u73fe\u308c\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Sudah bertemu janji selama satu jam sejak waktu yang dijanjikan, tetapi teman tidak muncul.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><strong>\u53d7\u3051\u53d6\u308b</strong>\uff08\u3046\u3051\u3068\u308b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menerima)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u7956<rt>\u305d</rt></ruby><ruby>\u6bcd<rt>\u307c</rt></ruby>\u304b\u3089\u3001\u304a\u7c73\u3084<ruby>\u679c<rt>\u304f\u3060</rt></ruby><ruby>\u7269<rt>\u3082\u306e</rt></ruby>\u306a\u3069\u305f\u304f\u3055\u3093\u306e<ruby>\u8377<rt>\u306b</rt></ruby><ruby>\u7269<rt>\u3082\u3064</rt></ruby>\u304c<u>\u53d7\u3051\u53d6\u3089\u308c\u3066</u>\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Dari nenek, banyak paket seperti beras dan buah-buahan diterima datang.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. 10\u5e74\u3082<ruby>\u9003<rt>\u306b</rt></ruby>\u3052\u3066\u3044\u305f\u304c\u3001\u3068\u3046\u3068\u3046<ruby>\u8b66<rt>\u3051\u3044</rt></ruby><ruby>\u5bdf<rt>\u3055\u3064</rt></ruby>\u306b<u>\u53d7\u3051\u53d6\u3063\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Sudah melarikan diri selama 10 tahun, tetapi akhirnya menerima oleh polisi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u4ed5\u4e8b\u306e\u30e1\u30fc\u30eb\u306f<u>\u53d7\u3051\u53d6\u3063\u305f\u3089</u>\u3059\u3050\u306b\u8fd4\u4e8b\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Email pekerjaan selalu langsung saya balas begitu menerimanya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u673a\u304c\u91cd\u3044\u306e\u3067\u3001\u53cb\u9054\u306b\u3068\u306a\u308a\u306e\u6559\u5ba4\u307e\u3067\u4e00\u7dd2\u306b<u>\u53d7\u3051\u53d6\u3063\u3066</u>\u3082\u3089\u3046\u3002</div>\n      <div class=\"q-id-trans\">Karena mejanya berat, saya meminta teman bersama-sama menerima ke ruang kelas sebelah.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><strong><ruby>\u7e70<rt>\u304f</rt></ruby>\u308a\u8fd4\u3059</strong>\uff08\u304f\u308a\u304b\u3048\u3059\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(mengulang / melakukan berulang kali)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5fd8\u308c\u7269\u3092\u3057\u3066\u3057\u307e\u3063\u3066\u3001\u5bb6\u3068\u99c5\u306e\u3042\u3044\u3060\u3092\u81ea\u8ee2\u8eca\u3067<u><ruby>\u7e70<rt>\u304f</rt></ruby>\u308a\u8fd4\u3057\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Karena ada barang tertinggal, saya mengulang antara rumah dan stasiun dengan sepeda.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u307e\u3060\u3088\u304f\u7406\u89e3\u3057\u3066\u3044\u306a\u3044\u306e\u3067\u3001\u3082\u3046\u4e00\u5ea6\u8aac\u660e\u3092<u><ruby>\u7e70<rt>\u304f</rt></ruby>\u308a\u8fd4\u3057\u3066</u>\u3044\u305f\u3060\u3051\u307e\u305b\u3093\u304b\uff1f</div>\n      <div class=\"q-id-trans\">Karena masih belum begitu mengerti, bisakah Anda mengulangi penjelasannya sekali lagi?</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <ruby>\u643a<rt>\u3051\u3044</rt></ruby><ruby>\u5e2f<rt>\u305f\u3044</rt></ruby><ruby>\u96fb<rt>\u3067\u3093</rt></ruby><ruby>\u8a71<rt>\u308f</rt></ruby>\u306e\u306a\u3044\u6642\u4ee3\u306f\u3001\u306e\u3093\u3073\u308a\u3068\u624b\u7d19\u3092<u><ruby>\u7e70<rt>\u304f</rt></ruby>\u308a\u8fd4\u3059</u>\u306e\u304c\u697d\u3057\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Pada zaman belum ada ponsel, mengulangi surat dengan santai sangat menyenangkan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <ruby>\u96ea<rt>\u3086\u304d</rt></ruby>\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u308b\u3068\u3001<ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u3068<ruby>\u96ea<rt>\u3086\u304d</rt></ruby><ruby>\u904a<rt>\u3042\u305d</rt></ruby>\u3073\u3057\u305f\u65e5\u306e\u3053\u3068\u3092<u><ruby>\u7e70<rt>\u304f</rt></ruby>\u308a\u8fd4\u3057\u307e\u3059</u>\u3002</div>\n      <div class=\"q-id-trans\">Setiap kali salju turun, saya mengulangi hari ketika bermain salju bersama keluarga.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><strong>\u53d6\u308a<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080</strong>\uff08\u3068\u308a\u3053\u3080\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(memasukkan dari luar ke dalam (mis. jemuran))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5c0f\u3055\u3044\u6bb5\u30dc\u30fc\u30eb\u7bb1\u306b<ruby>\u732b<rt>\u306d\u3053</rt></ruby>\u304c<u>\u53d6\u308a<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3093\u3067</u>\u3001\u663c\u5bdd\u3092\u3057\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Kucing memasukkan ke dalam kardus kecil dan tidur siang.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u6d17\u3063\u3066\u304d\u308c\u3044\u306b\u306a\u3063\u305f\u6d0b\u670d\u3092\u30bf\u30f3\u30b9\u306b<u>\u53d6\u308a<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3080</u>\u6bcd\u306e\u624b\u4f1d\u3044\u3092\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Membantu ibu memasukkan ke dalam lemari pakaian baju yang sudah dicuci bersih.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u30b9\u30fc\u30d1\u30fc\u3067\u8cb7\u3063\u305f\u54c1\u7269\u3092\u81ea\u5206\u306e\u304b\u3070\u3093\u306b<u>\u53d6\u308a<ruby>\u8fbc<rt>\u3053</rt></ruby>\u3093\u3067</u>\u3001\u6301\u3063\u3066\u5e30\u308b\u3002</div>\n      <div class=\"q-id-trans\">Memasukkan barang yang dibeli di supermarket ke dalam tas sendiri, lalu membawanya pulang.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u96e8\u304c<ruby>\u964d<rt>\u3075</rt></ruby>\u308a\u3060\u3059\u524d\u306b\u3001\u6d17\u6fef\u7269\u3092<u>\u53d6\u308a<ruby>\u8fbc<rt>\u3053</rt></ruby>\u307e\u306a\u3044\u3068</u>\u3044\u3051\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Sebelum hujan mulai turun, kita harus memasukkan (mengangkat) jemuran.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><strong>\u843d\u3061\u7740\u304f</strong>\uff08\u304a\u3061\u3064\u304f\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(tenang / menenangkan diri)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u304c<u>\u843d\u3061\u7740\u3044\u305f</u>\u9854\u3092\u3057\u3066\u3044\u305f\u306e\u3067\u3001<ruby>\u5fc3<rt>\u3057\u3093</rt></ruby><ruby>\u914d<rt>\u3071\u3044</rt></ruby>\u306b\u306a\u308a\u58f0\u3092\u304b\u3051\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena teman menunjukkan wajah yang tenang, saya menjadi khawatir lalu menyapanya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <u>\u843d\u3061\u7740\u3044\u3066</u>\u8aad\u66f8\u3084\u4ed5\u4e8b\u3092\u3057\u305f\u3044\u3068\u304d\u306f\u3001<ruby>\u9759<rt>\u3057\u305a</rt></ruby>\u304b\u306a\u30ab\u30d5\u30a7\u306b\u884c\u304f\u3002</div>\n      <div class=\"q-id-trans\">Saat ingin membaca buku atau bekerja dengan tenang, saya pergi ke kafe yang sunyi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u308f\u305f\u3057\u304c\u4f4f\u3093\u3067\u3044\u308b<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u306f10\u968e\u3060\u3051\u3069\u3001\u30a8\u30ec\u30d9\u30fc\u30bf\u30fc\u3067<u>\u843d\u3061\u7740\u3044\u3066</u>\u3044\u3051\u3070\u3059\u30501\u968e\u306b\u7740\u304d\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Kamar tempat saya tinggal ada di lantai 10, tetapi kalau pergi dengan tenang naik lift, langsung sampai di lantai 1.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u99c5\u306e<ruby>\u968e<rt>\u304b\u3044</rt></ruby><ruby>\u6bb5<rt>\u3060\u3093</rt></ruby>\u306b\u30cd\u30c3\u30af\u30ec\u30b9\u304c<u>\u843d\u3061\u7740\u3044\u305f</u>\u306e\u3067\u3001\u7a93\u53e3\u306b<ruby>\u5c4a<rt>\u3068\u3069</rt></ruby>\u3051\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena kalung tenang di tangga stasiun, saya menyerahkannya ke loket.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><strong>\u77e5\u308a\u5408\u3046</strong>\uff08\u3057\u308a\u3042\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(berkenalan / saling mengenal)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u60b2\u3057\u3044\u3068\u304d\u306f\u3001\u308f\u305f\u3057\u306e\u3053\u3068\u3092\u3088\u304f<u>\u77e5\u308a\u5408\u3063\u3066</u>\u304f\u308c\u3066\u3044\u308b\u53cb\u4eba\u3068\u8a71\u3092\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Saat sedih, saya mengobrol dengan teman yang sangat berkenalan tentang diri saya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u4ed5\u4e8b\u5e30\u308a\u3001\u96fb\u8eca\u306b\u4e57\u3063\u3066\u3044\u308b\u3068\u3001<ruby>\u5076<rt>\u3050\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby>\u9ad8\u6821\u306e\u540c\u7d1a\u751f\u3068<u>\u77e5\u308a\u5408\u3063\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Sepulang kerja, saat naik kereta, saya kebetulan berkenalan dengan teman sekelas waktu SMA.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u308f\u305f\u3057\u305f\u3061\u306f\u5927\u5b66\u3067<u>\u77e5\u308a\u5408\u3044</u>\u3001\u6570\u5e74\u4ed8\u304d\u5408\u3063\u305f\u5f8c\u3067\u7d50\u5a5a\u3057\u307e\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Kami berkenalan di universitas, lalu menikah setelah berpacaran beberapa tahun.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u590f\u4f11\u307f\u306f<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306e\u5bb6\u306b\u96c6\u307e\u3063\u3066\u3001\u82e6\u624b\u306a<ruby>\u79d1<rt>\u304b</rt></ruby><ruby>\u76ee<rt>\u3082\u304f</rt></ruby>\u306e<ruby>\u5bbf<rt>\u3057\u3085\u304f</rt></ruby><ruby>\u984c<rt>\u3060\u3044</rt></ruby>\u306e\u7b54\u3048\u3092<u>\u77e5\u308a\u5408\u3063\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Saat liburan musim panas kami berkumpul di rumah teman dan saling berkenalan jawaban PR mata pelajaran yang sulit.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span><strong>\u5f15\u304d\u51fa\u3059</strong>\uff08\u3072\u304d\u3060\u3059\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menarik (uang) / mengeluarkan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u96e8\u306e\u65e5\u306f\u3001\u7121\u7406\u306b\u72ac\u3092\u5916\u306b<u>\u5f15\u304d\u51fa\u3059</u>\u5fc5\u8981\u306f\u306a\u3044\u3067\u3059\u3088\u3002</div>\n      <div class=\"q-id-trans\">Pada hari hujan, tidak perlu memaksa menarik anjing ke luar rumah.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <ruby>\u81ea<rt>\u3058</rt></ruby><ruby>\u52d5<rt>\u3069\u3046</rt></ruby><ruby>\u8ca9<rt>\u306f\u3093</rt></ruby><ruby>\u58f2<rt>\u3070\u3044</rt></ruby><ruby>\u6a5f<rt>\u304d</rt></ruby>\u3067\u30b8\u30e5\u30fc\u30b9\u3092\u8cb7\u3063\u305f\u3089\u3001\u304a\u3064\u308a\u3092\u5fd8\u308c\u306a\u3044\u3067<u>\u5f15\u304d\u51fa\u3057\u3066</u>\u306d\u3002</div>\n      <div class=\"q-id-trans\">Setelah membeli jus di mesin penjual otomatis, jangan lupa menarik uang kembaliannya, ya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u4f1a\u793e\u306e<ruby>\u51b7<rt>\u308c\u3044</rt></ruby><ruby>\u8535<rt>\u305e\u3046</rt></ruby><ruby>\u5eab<rt>\u3053</rt></ruby>\u306b\u5165\u308c\u305f\u98df\u3079\u7269\u306f\u3001\u9031\u672b\u306b\u306f\u5fd8\u308c\u305a\u306b<u>\u5f15\u304d\u51fa\u3057\u3066</u>\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Makanan yang dimasukkan ke kulkas perusahaan, harap jangan lupa menariknya pada akhir pekan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u304a\u7d66\u6599\u3092<u>\u5f15\u304d\u51fa\u3059</u>\u304b\u3089\u3001\u4eca\u65e5\u306f\u9280\u884c\u306b<ruby>\u5bc4<rt>\u3088</rt></ruby>\u3063\u3066\u304b\u3089\u5e30\u308b\u306d\u3002</div>\n      <div class=\"q-id-trans\">Karena ingin menarik gaji, hari ini saya mampir ke bank dulu baru pulang.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span><strong>\u8ffd\u3044<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3059</strong>\uff08\u304a\u3044\u3053\u3059\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(menyalip / mendahului)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u3044\u3064\u3082\u901a\u3063\u3066\u3044\u308b<ruby>\u7f8e<rt>\u3073</rt></ruby><ruby>\u5bb9<rt>\u3088\u3046</rt></ruby><ruby>\u9662<rt>\u3044\u3093</rt></ruby>\u306e\u524d\u3092\u8eca\u3067<u>\u8ffd\u3044<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Saya menyalip bagian depan salon kecantikan yang biasa saya datangi dengan mobil.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u904b\u8ee2\u3057\u3066\u3044\u305f\u3089\u3001\u6025\u306b\u5b50\u3069\u3082\u304c\u9053\u8def\u306b<u>\u8ffd\u3044<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057\u3066</u>\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat sedang menyetir, tiba-tiba ada anak kecil menyalip ke jalan raya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u524d\u3092\u6b69\u3044\u3066\u3044\u305f\u72ac\u304c\u3053\u3063\u3061\u306b\u5411\u304b\u3063\u3066\u6025\u306b<u>\u8ffd\u3044<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Anjing yang tadinya berjalan di depan tiba-tiba menyalip ke arah sini.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u6025\u3044\u3067\u3044\u305f\u306e\u3067\u3001\u524d\u3092\u8d70\u3063\u3066\u3044\u308b\u8eca\u3092<u>\u8ffd\u3044<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Karena sedang terburu-buru, saya menyalip mobil yang melaju di depan.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><strong>\u53d6\u308a\u6d88\u3059</strong>\uff08\u3068\u308a\u3051\u3059\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(membatalkan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u6d77\u5916\u7559\u5b66\u3092\u3059\u308b\u305f\u3081\u306b\u3001\u4f1a\u793e\u3092<u>\u53d6\u308a\u6d88\u3057\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Demi kuliah ke luar negeri, saya membatalkan perusahaan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u96fb\u6c17\u304c\u3064\u304b\u306a\u304f\u306a\u3063\u305f\u3089\u3001\u96fb\u7403\u3092<u>\u53d6\u308a\u6d88\u3059</u>\u5fc5\u8981\u304c\u3042\u308b\u3002</div>\n      <div class=\"q-id-trans\">Jika lampu tidak mau menyala lagi, perlu membatalkan bola lampunya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5b89\u5168\u904b\u8ee2\u306f\u3001<ruby>\u4ea4<rt>\u3053\u3046</rt></ruby><ruby>\u901a<rt>\u3064\u3046</rt></ruby><ruby>\u4e8b<rt>\u3058</rt></ruby><ruby>\u6545<rt>\u3053</rt></ruby>\u3092<u>\u53d6\u308a\u6d88\u3059</u>\u3053\u3068\u304c\u3067\u304d\u308b\u3002</div>\n      <div class=\"q-id-trans\">Mengemudi dengan aman dapat membatalkan kecelakaan lalu lintas.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u6642\u9593\u306b\u9593\u306b\u5408\u308f\u306a\u3044\u306e\u3067\u3001\u30ec\u30b9\u30c8\u30e9\u30f3\u306e\u4e88\u7d04\u3092<u>\u53d6\u308a\u6d88\u3057\u305f</u>\u3002</div>\n      <div class=\"q-id-trans\">Karena tidak sempat tepat waktu, saya membatalkan reservasi restoran.</div>\n    </div>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 1\uff082 \u5f85\u3064 [menunggu]\u30fb3 \u5f85\u3063\u3066 [menunggu]\u30fb4 \u5f85\u3063\u3066 [menunggu]\uff09\u3000\u2461 3\uff081 \u9001\u3089\u308c\u3066 [dikirimkan]\u30fb2 \u3064\u304b\u307e\u3063\u305f [ditangkap]\u30fb4 \u6301\u3063\u3066 [membawa]\uff09\u3000\u2462 2\uff081 \u5f80\u5fa9\u3057\u305f [bolak-balik]\u30fb3 \u3084\u308a\u53d6\u308a\u3059\u308b [saling bertukar]\u30fb4 \u601d\u3044\u51fa\u3059 [mengingat kembali]\uff09\u3000\u2463 4\uff081 \u5165\u308a\u8fbc\u3093\u3067 [masuk ke dalam]\u30fb2 \u3057\u307e\u3046 [menyimpan]\u30fb3 \u5165\u308c\u3066 [memasukkan]\uff09\u3000\u2464 2\uff081 \u843d\u3061\u8fbc\u3093\u3060 [murung/sedih]\u30fb3 \u964d\u308a\u3066 [turun]\u30fb4 \u843d\u3061\u3066\u3044\u305f [terjatuh]\uff09\u3000\u2465 3\uff081 \u7406\u89e3\u3057\u3066 [memahami]\u30fb2 \u4f1a\u3063\u305f [bertemu]\u30fb4 \u6559\u3048\u5408\u3063\u305f [saling mengajari]\uff09\u3000\u2466 4\uff081 \u9023\u308c\u51fa\u3059 [membawa keluar]\u30fb2 \u53d6\u3063\u3066 [mengambil]\u30fb3 \u6301\u3061\u5e30\u3063\u3066 [membawa pulang]\uff09\u3000\u2467 4\uff081 \u901a\u308a\u304b\u304b\u3063\u305f [melewati]\u30fb2 \u98db\u3073\u51fa\u3057\u3066 [melompat keluar]\u30fb3 \u99c6\u3051\u51fa\u3057\u305f [berlari ke arah]\uff09\u3000\u2468 4\uff081 \u8f9e\u3081\u305f [berhenti/keluar]\u30fb2 \u53d6\u308a\u66ff\u3048\u308b [mengganti]\u30fb3 \u9632\u3050 [mencegah]\uff09</div>\n<h3>Latihan 5 \u00b7 Mondai 5: Kata Sifat (Hal. Buku 114-115)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu penggunaan kata yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span><strong>\u78ba\u5b9f</strong>\uff08\u304b\u304f\u3058\u3064\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pasti / meyakinkan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068\u8a71\u3057\u3066\u3044\u305f\u3053\u3068\u304c\u300110\u5e74\u5f8c\u5168\u3066<u>\u78ba\u5b9f</u>\u306b\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Hal yang dulu dibicarakan bersama teman, 10 tahun kemudian semuanya menjadi pasti.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u3082\u3046\u4e8c\u5ea6\u3068<u>\u78ba\u5b9f</u>\u306e\u5931\u6557\u3068\u540c\u3058\u3053\u3068\u3092\u3084\u3089\u306a\u3044\u3088\u3046\u306b\u3001\u30eb\u30fc\u30eb\u304c\u4f5c\u3089\u308c\u308b\u3002</div>\n      <div class=\"q-id-trans\">Dibuat aturan agar jangan sampai mengulangi hal yang sama dengan kegagalan yang pasti untuk kedua kalinya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u7d04\u675f\u306e\u4e00\u6642\u9593\u524d\u306b\u306f\u3001<u>\u78ba\u5b9f</u>\u306b\u76ee\u7684\u306e\u5834\u6240\u306b\u7740\u304f\u3088\u3046\u306b\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Pastikan (usahakan secara pasti) tiba di tempat tujuan satu jam sebelum waktu yang dijanjikan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u76f8\u624b\u304c<u>\u78ba\u5b9f</u>\u306b\u4f55\u3092\u8003\u3048\u3066\u3044\u308b\u306e\u304b\u3001\u3061\u3083\u3093\u3068\u805e\u3044\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Tolong dengarkan baik-baik apa yang dipikirkan lawan bicara secara pasti.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><strong>\u53ef\u80fd</strong>\uff08\u304b\u306e\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(mungkin / dapat dilakukan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u308f\u305f\u3057\u306f\u3069\u3046\u3057\u3066\u3082\u5bb6\u4e8b\u304c<u>\u53ef\u80fd</u>\u306a\u306e\u3067\u3001\u305d\u3046\u3058\u306f\u6a5f\u68b0\u306b\u4efb\u305b\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Karena saya bagaimanapun juga sangat mungkin pekerjaan rumah, urusan bersih-bersih saya serahkan ke mesin.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u4f11\u65e5\u306b<ruby>\u51fa<rt>\u3057\u3085\u3063</rt></ruby><ruby>\u52e4<rt>\u304d\u3093</rt></ruby>\u3059\u308b\u3053\u3068\u3082<u>\u53ef\u80fd</u>\u3067\u3059\u304c\u3001\u7d66\u6599\u306f\u3044\u3064\u3082\u3088\u308a\u591a\u304f\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Masuk kerja di hari libur juga memungkinkan (dapat dilakukan), tetapi tolong buat gajinya lebih banyak dari biasanya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3042\u306a\u305f\u306f\u3068\u3066\u3082<u>\u53ef\u80fd</u>\u306a\u5973\u6027\u3060\u304b\u3089\u3001\u65b0\u3057\u3044\u4ed5\u4e8b\u3082<ruby>\u6210<rt>\u305b\u3044</rt></ruby><ruby>\u529f<rt>\u3053\u3046</rt></ruby>\u3057\u307e\u3059\u3088\u3002</div>\n      <div class=\"q-id-trans\">Karena Anda adalah wanita yang sangat mungkin, pekerjaan baru pun pasti akan berhasil.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u308f\u305f\u3057\u306f\u6642\u9593\u304c\u306a\u304f\u3066<u>\u53ef\u80fd</u>\u3067\u3059\u304b\u3089\u3001\u4ed6\u306e\u65b9\u306b<ruby>\u983c<rt>\u305f\u306e</rt></ruby>\u3093\u3067\u307f\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Karena saya tidak punya waktu sehingga mungkin, coba minta kepada orang lain.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><strong>\u6b63\u5e38</strong>\uff08\u305b\u3044\u3058\u3087\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(normal / wajar)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u6bce\u65e5\u3001\u6a5f\u68b0\u304c<u>\u6b63\u5e38</u>\u306b\u52d5\u3044\u3066\u3044\u308b\u304b\u3092\u78ba\u8a8d\u3057\u3066\u304b\u3089\u4ed5\u4e8b\u3092\u59cb\u3081\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Setiap hari saya memulai pekerjaan setelah memastikan apakah mesin bergerak dengan normal.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u5c71\u306e\u4e0a\u306b\u767b\u3063\u3066\u3001<u>\u6b63\u5e38</u>\u306a\u7a7a\u6c17\u306e\u4e2d\u3067\u3054\u98ef\u3092\u98df\u3079\u308b\u306e\u306f\u6700\u9ad8\u3060\u3002</div>\n      <div class=\"q-id-trans\">Mendaki ke atas gunung lalu makan nasi di tengah udara yang normal adalah hal terbaik.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f7c\u5973\u306f\u3068\u3066\u3082<u>\u6b63\u5e38</u>\u306a\u6027\u683c\u306a\u306e\u3067\u3001\u4f1a\u793e\u306e\u307f\u3093\u306a\u304b\u3089\u597d\u304b\u308c\u3066\u3044\u308b\u3002</div>\n      <div class=\"q-id-trans\">Karena dia berkepribadian sangat normal, dia disukai oleh semua orang di perusahaan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u3053\u306e\u89d2\u3092\u66f2\u304c\u3063\u3066<u>\u6b63\u5e38</u>\u306b\u9032\u3080\u3068\u3001<ruby>\u90f5<rt>\u3086\u3046</rt></ruby><ruby>\u4fbf<rt>\u3073\u3093</rt></ruby><ruby>\u5c40<rt>\u304d\u3087\u304f</rt></ruby>\u304c\u3042\u308a\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Jika belok di sudut ini lalu maju dengan normal, ada kantor pos.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><strong>\u8eab\u8fd1</strong>\uff08\u307f\u3062\u304b\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(dekat / akrab dalam keseharian)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u52c9\u5f37\u3057\u306a\u3044\u3067\u904a\u3093\u3067\u3070\u304b\u308a\u3044\u305f\u3089\u3001\u8a66\u9a13\u306e\u65e5\u304c<u>\u8eab\u8fd1</u>\u306b\u306a\u3063\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena hanya bermain terus tanpa belajar, hari ujian menjadi dekat.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u5efa\u7269\u3068\u5efa\u7269\u306e\u9593\u304c<u>\u8eab\u8fd1</u>\u3059\u304e\u3066\u3001\u9593\u3092\u901a\u308b\u3053\u3068\u304c\u3067\u304d\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Jarak antara gedung dan gedung terlalu dekat, sehingga tidak bisa lewat di antaranya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f7c\u3068\u308f\u305f\u3057\u306f\u3001\u5c0f\u5b66\u6821\u3067\u51fa\u4f1a\u3063\u3066<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306b\u306a\u3063\u3066\u304b\u3089\u3001\u305a\u3063\u3068<u>\u8eab\u8fd1</u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Dia dan saya sejak bertemu dan berteman di SD, selalu akrab/dekat.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5b50\u3069\u3082\u306e\u3068\u304d\u304b\u3089\u305a\u3063\u3068\u72ac\u3092<ruby>\u98fc<rt>\u304b</rt></ruby>\u3063\u3066\u3044\u308b\u306e\u3067\u3001\u72ac\u306f<u>\u8eab\u8fd1</u>\u306a\u5b58\u5728\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Karena memelihara anjing terus sejak kecil, anjing adalah keberadaan yang dekat/akrab bagi saya.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><strong>\u6025</strong>\uff08\u304d\u3085\u3046\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(mendadak / tiba-tiba)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <u>\u6025</u>\u306b<ruby>\u51fa<rt>\u3057\u3085\u3063</rt></ruby><ruby>\u5f35<rt>\u3061\u3087\u3046</rt></ruby>\u3059\u308b\u3088\u3046\u306b\u8a00\u308f\u308c\u3001\u3042\u308f\u3066\u3066\u30b9\u30fc\u30c4\u30b1\u30fc\u30b9\u3084\u8863\u985e\u3092\u6e96\u5099\u3092\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Tiba-tiba disuruh dinas luar kota, sehingga dengan panik menyiapkan koper dan pakaian.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u4f1a\u793e\u304b\u3089\u306e\u9023\u7d61\u306b\u306f\u3001<ruby>\u5fd9<rt>\u3044\u305d\u304c</rt></ruby>\u3057\u304f\u3066\u3082\u6c17\u3065\u3044\u305f\u3089<u>\u6025</u>\u306b\u8fd4\u4e8b\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Balasan untuk kabar dari perusahaan, meski sibuk kalau sadar saya membalasnya dengan mendadak.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u304a<ruby>\u8179<rt>\u306a\u304b</rt></ruby>\u304c\u75db\u304f\u3066\u82e6\u3057\u3080\u308f\u305f\u3057\u3092\u898b\u3066\u3001<ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u306f<u>\u6025</u>\u3067\u85ac\u3092\u8cb7\u3063\u3066\u304d\u3066\u304f\u308c\u305f\u3002</div>\n      <div class=\"q-id-trans\">Melihat saya menderita sakit perut, keluarga membelikan obat dengan mendadak.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u7d04\u675f\u306e\u6642\u9593\u306b<ruby>\u9045<rt>\u3061</rt></ruby><ruby>\u523b<rt>\u3053\u304f</rt></ruby>\u3057\u306a\u3044\u3088\u3046\u3001<u>\u6025</u>\u306b\u5bb6\u3092\u51fa\u305f\u3002</div>\n      <div class=\"q-id-trans\">Agar tidak terlambat dari waktu janji, saya keluar rumah dengan mendadak.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><strong>\u4e0a\u54c1</strong>\uff08\u3058\u3087\u3046\u3072\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(elegan / berkelas / halus)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5916\u56fd\u8a9e\u3092\u8a71\u3059\u3053\u3068\u304c\u3067\u304d\u308b\u5f7c\u5973\u306f\u3001<u>\u4e0a\u54c1</u>\u306a\u4f1a\u793e\u306b<ruby>\u5c31<rt>\u3057\u3085\u3046</rt></ruby><ruby>\u8077<rt>\u3057\u3087\u304f</rt></ruby>\u3059\u308b\u3053\u3068\u304c\u6c7a\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Dia yang dapat berbicara bahasa asing diterima bekerja di perusahaan yang elegan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u6d77\u5916\u306b\u7559\u5b66\u3057\u3066\u3044\u305f\u5f7c\u306e\u82f1\u8a9e\u306e\u6210\u7e3e\u306f\u3001<u>\u4e0a\u54c1</u>\u3067\u3059\u3002</div>\n      <div class=\"q-id-trans\">Nilai bahasa Inggrisnya yang pernah kuliah di luar negeri sangat elegan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3053\u306e\u30ec\u30b9\u30c8\u30e9\u30f3\u306e\u30b1\u30fc\u30ad\u306f\u3001<u>\u4e0a\u54c1</u>\u306a\u5473\u304c\u3059\u308b\u3002</div>\n      <div class=\"q-id-trans\">Kue di restoran ini memiliki rasa yang elegan/berkelas.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u3053\u3093\u306a\u306b\u9060\u304f\u3060\u3068\u3001\u76ee\u304c\u60aa\u3044\u59b9\u306f\u6620\u753b\u3092<u>\u4e0a\u54c1</u>\u306b\u307f\u308b\u3053\u3068\u304c\u3067\u304d\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Kalau sejauh ini, adik perempuan yang matanya kurang baik tidak bisa menonton film dengan elegan.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span><strong><ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby></strong>\uff08\u3081\u3044\u308f\u304f\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(mengganggu / merepotkan)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u6563<rt>\u3061</rt></ruby>\u3089\u304b\u3063\u305f\u81ea\u5206\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u3092\u4e00\u4eba\u3067<ruby>\u6383<rt>\u305d\u3046</rt></ruby><ruby>\u9664<rt>\u3058</rt></ruby>\u3059\u308b\u306e\u306f\u3068\u3066\u3082<u><ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby></u>\u3060\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Membersihkan kamar sendiri yang berantakan sendirian sangat mengganggu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u96a3\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u306e\u4eba\u304c\u6bce\u6669<ruby>\u9a12<rt>\u3055\u308f</rt></ruby>\u3044\u3067\u3044\u3066\u3001\u3068\u3066\u3082<u><ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby></u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Orang di kamar sebelah berisik setiap malam, sangat mengganggu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <ruby>\u5f15<rt>\u3072</rt></ruby>\u3063<ruby>\u8d8a<rt>\u3053</rt></ruby>\u3057\u3092\u3059\u308b\u3068\u3001\u8272\u3005\u306a<ruby>\u7533<rt>\u3057\u3093</rt></ruby><ruby>\u8acb<rt>\u305b\u3044</rt></ruby><ruby>\u66f8<rt>\u3057\u3087</rt></ruby>\u304c\u5fc5\u8981\u306b\u306a\u308b\u306e\u3067<u><ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby></u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Saat pindah rumah, karena diperlukan berbagai surat permohonan, itu sangat mengganggu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u4eca\u65e5\u306f\u6d77\u306b\u884c\u304f\u4e88\u5b9a\u3060\u304c\u3001\u592a\u967d\u304c<ruby>\u96f2<rt>\u304f\u3082</rt></ruby>\u3067<ruby>\u96a0<rt>\u304b\u304f</rt></ruby>\u308c\u3066\u3044\u3066\u5929\u6c17\u304c<u><ruby>\u8ff7<rt>\u3081\u3044</rt></ruby><ruby>\u60d1<rt>\u308f\u304f</rt></ruby></u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Hari ini rencananya pergi ke pantai, tetapi matahari tertutup awan sehingga cuacanya mengganggu.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span><strong>\u4e0d\u5b89</strong>\uff08\u3075\u3042\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(cemas / gelisah / khawatir)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u6700\u5f8c\u306e\u8a66\u5408\u306a\u306e\u306b\u3001\u4e00\u70b9\u306e\u5dee\u3067\u8ca0\u3051\u3066\u3057\u307e\u3063\u3066<u>\u4e0d\u5b89</u>\u3060\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Padahal pertandingan terakhir, kalah dengan selisih satu poin sehingga saya merasa cemas.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u307f\u3093\u306a\u306e\u524d\u3067\u5931\u6557\u3057\u305f\u3053\u3068\u304c<u>\u4e0d\u5b89</u>\u3060\u3063\u305f\u306e\u3067\u3001<ruby>\u9003<rt>\u306b</rt></ruby>\u3052\u51fa\u3057\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena gagal di depan semua orang terasa cemas, saya melarikan diri.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <ruby>\u51b7<rt>\u308c\u3044</rt></ruby><ruby>\u8535<rt>\u305e\u3046</rt></ruby><ruby>\u5eab<rt>\u3053</rt></ruby>\u306b\u5165\u3063\u3066\u3044\u308b\u5f7c\u5973\u306e\u30d7\u30ea\u30f3\u3092\u98df\u3079\u305f\u3089\u3001<u>\u4e0d\u5b89</u>\u3060\u308d\u3046\u306a\u3042\u3002</div>\n      <div class=\"q-id-trans\">Kalau memakan puding miliknya yang ada di kulkas, pasti akan cemas ya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5a18\u304c<ruby>\u8ff7\u5b50<rt>\u307e\u3044\u3054</rt></ruby>\u306b\u306a\u3063\u305f\u3068\u304d\u306f\u3001\u767a\u898b\u3055\u308c\u308b\u307e\u3067<u>\u4e0d\u5b89</u>\u3067\u3057\u3087\u3046\u304c\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Ketika anak perempuan saya tersesat (menjadi anak hilang), sampai ditemukan saya sangat cemas luar biasa.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><strong><ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u7d14<rt>\u3058\u3085\u3093</rt></ruby></strong>\uff08\u305f\u3093\u3058\u3085\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(sederhana / simpel)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u65b0\u3057\u304f\u8cb7\u3063\u305f<ruby>\u9774<rt>\u304f\u3064</rt></ruby>\u306f\u3001\u3068\u3066\u3082<u><ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u7d14<rt>\u3058\u3085\u3093</rt></ruby></u>\u3067\u6b69\u304d\u3084\u3059\u3044\u3002</div>\n      <div class=\"q-id-trans\">Sepatu yang baru dibeli sangat sederhana dan nyaman dipakai berjalan.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u307f\u3093\u306a\u304c\u308f\u304b\u3089\u306a\u304b\u3063\u305f\u554f\u984c\u3092\u3001\u5f7c\u306f<u><ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u7d14<rt>\u3058\u3085\u3093</rt></ruby></u>\u306b\u89e3\u3044\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Soal yang tidak dimengerti semua orang, dia memecahkannya dengan sederhana.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3053\u306e\u4ed5\u4e8b\u306f<u><ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u7d14<rt>\u3058\u3085\u3093</rt></ruby></u>\u306b\u898b\u3048\u308b\u304c\u3001\u5b9f\u306f<ruby>\u8907<rt>\u3075\u304f</rt></ruby><ruby>\u96d1<rt>\u3056\u3064</rt></ruby>\u3067\u96e3\u3057\u3044\u3002</div>\n      <div class=\"q-id-trans\">Pekerjaan ini terlihat sederhana, tetapi sebenarnya rumit dan sulit.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5bb6\u306e\u524d\u306b\u3042\u308b\u5742\u9053\u306f\u3001\u81ea\u8ee2\u8eca\u3088\u308a\u3082\u6b69\u3044\u3066\u767b\u3063\u305f\u65b9\u304c<u><ruby>\u5358<rt>\u305f\u3093</rt></ruby><ruby>\u7d14<rt>\u3058\u3085\u3093</rt></ruby></u>\u3060\u3002</div>\n      <div class=\"q-id-trans\">Jalan menanjak di depan rumah lebih sederhana jika didaki dengan berjalan kaki daripada naik sepeda.</div>\n    </div>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 3\uff081 \u73fe\u5b9f [kenyataan]\u30fb2 \u904e\u53bb [masa lalu]\u30fb4 \u5b9f\u969b [sebenarnya]\uff09\u3000\u2461 2\uff081 \u82e6\u624b [tidak ahli/lemah]\u30fb3 \u6709\u80fd [kompeten/berbakat]\u30fb4 \u3067\u304d\u307e\u305b\u3093 [tidak bisa]\uff09\u3000\u2462 1\uff082 \u65b0\u9bae [segar]\u30fb3 \u6b63\u76f4 [jujur]\u30fb4 \u307e\u3063\u3059\u3050 [lurus]\uff09\u3000\u2463 4\uff081 \u8fd1\u3065\u3044\u3066 [mendekat]\u30fb2 \u8fd1\u3059\u304e\u3066 [terlalu sempit/dekat]\u30fb3 \u4ef2\u826f\u3057 [akrab]\uff09\u3000\u2464 1\uff082 \u3059\u3050\u306b [segera]\u30fb3 \u6025\u3044\u3067 [buru-buru]\u30fb4 \u65e9\u3081\u306b [lebih awal]\uff09\u3000\u2465 3\uff081 \u4e00\u6d41 [kelas satu]\u30fb2 \u3044\u3044 [bagus]\u30fb4 \u3088\u304f [dengan jelas/baik]\uff09\u3000\u2466 2\uff081 \u5927\u5909 [berat]\u30fb3 \u9762\u5012 [merepotkan/ribet]\u30fb4 \u5fc3\u914d [khawatir]\uff09\u3000\u2467 4\uff081 \u6094\u3057\u304b\u3063\u305f [kesal/menyesal]\u30fb2 \u6065\u305a\u304b\u3057\u304f\u3066 [malu]\u30fb3 \u6012\u308b [marah]\uff09\u3000\u2468 3\uff081 \u8efd\u304f\u3066 [ringan]\u30fb2 \u7c21\u5358 [mudah]\u30fb4 \u697d [nyaman/enteng]\uff09</div>\n<h3>Latihan 6 \u00b7 Mondai 5: Kata Keterangan / Fukushi (Hal. Buku 116-117)</h3>\n<p style=\"font-size:9.3pt; color:#475569; margin:4px 0 8px 0;\">\u554f\u984c5\u3000\u3064\u304e\u306e\u3053\u3068\u3070\u306e\u4f7f\u3044\u65b9\u3068\u3057\u3066\u6700\u3082\u3088\u3044\u3082\u306e\u3092\u30011\u30fb2\u30fb3\u30fb4\u304b\u3089\u4e00\u3064\u3048\u3089\u3073\u306a\u3055\u3044\u3002 <em>(Pilihlah satu penggunaan kata yang paling tepat dari pilihan 1, 2, 3, atau 4.)</em></p>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">1</span><strong>\u305b\u3063\u304b\u304f</strong> <small style=\"color:#1b5e20; font-weight:600;\">(sudah susah-susah / sayang sekali)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u3042\u3093\u306a\u306b\u52c9\u5f37\u3057\u305f\u306e\u306b\u3001\u30c6\u30b9\u30c8<ruby>\u5f53<rt>\u3068\u3046</rt></ruby><ruby>\u65e5<rt>\u3058\u3064</rt></ruby>\u306f<u>\u305b\u3063\u304b\u304f</u>\u554f\u984c\u3092\u89e3\u3051\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Padahal sudah belajar sebanyak itu, pada hari ujian saya susah-susah tidak bisa mengerjakan soal.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u304b\u305c\u3092\u3072\u3044\u3066\u3057\u307e\u3063\u3066\u3001<u>\u305b\u3063\u304b\u304f</u>\u547c\u3093\u3067\u3082\u3089\u3063\u305f\u30d1\u30fc\u30c6\u30a3\u30fc\u306b\u53c2\u52a0\u3067\u304d\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Karena terkena flu, saya tidak bisa ikut pesta yang padahal sudah susah-susah mengundang saya (sayang sekali).</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f7c\u5973\u304c\u6765\u308b\u306e\u3092\u5f85\u3063\u3066\u307f\u305f\u3051\u3069\u3001<u>\u305b\u3063\u304b\u304f</u><ruby>\u6211<rt>\u304c</rt></ruby><ruby>\u6162<rt>\u307e\u3093</rt></ruby>\u3067\u304d\u306a\u304f\u306a\u3063\u3066\u5e30\u308b\u3053\u3068\u306b\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya sudah mencoba menunggu kedatangannya, tetapi susah-susah tidak tahan lagi sehingga memutuskan pulang.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u52aa\u529b\u3057\u3066\u3082\u3001<u>\u305b\u3063\u304b\u304f</u>\u3044\u3044\u7d50\u679c\u304c<ruby>\u5f97<rt>\u3048</rt></ruby>\u3089\u308c\u308b\u308f\u3051\u3067\u306f\u3042\u308a\u307e\u305b\u3093\u3002</div>\n      <div class=\"q-id-trans\">Meskipun berusaha, belum tentu susah-susah bisa mendapatkan hasil yang bagus.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">2</span><strong>\u7d50\u5c40</strong>\uff08\u3051\u3063\u304d\u3087\u304f\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(pada akhirnya / kesimpulannya)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u3053\u306e\u30b1\u30fc\u30ad\u306f<ruby>\u9ad8<rt>\u3053\u3046</rt></ruby><ruby>\u4fa1<rt>\u304b</rt></ruby>\u3060\u3063\u305f\u3051\u3069\u3001<u>\u7d50\u5c40</u>\u304a\u3044\u3057\u304f\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Kue ini mahal, tetapi pada akhirnya tidak enak.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u304c\u56f0\u3063\u3066\u3044\u308b\u3088\u3046\u3059\u3060\u3063\u305f\u3089<u>\u7d50\u5c40</u>\u52a9\u3051\u307e\u3059\u3088\u3002</div>\n      <div class=\"q-id-trans\">Kalau teman tampak sedang kesulitan, pada akhirnya saya akan membantunya, kok.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u4e00\u5e74\u9593\u3001\u305a\u3063\u3068\u5f7c\u304c\u5927\u597d\u304d\u3060\u3063\u305f\u3051\u3069\u3001<u>\u7d50\u5c40</u>\u604b\u4eba\u306b\u306f\u306a\u308c\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Selama satu tahun saya terus menyukainya, tetapi pada akhirnya tidak bisa menjadi pacar.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <ruby>\u5c71<rt>\u3084\u307e</rt></ruby><ruby>\u7530<rt>\u3060</rt></ruby>\u3055\u3093\u306e\u8a71\u3092\u3057\u3066\u3044\u305f\u3089\u3001<u>\u7d50\u5c40</u>\u5f7c\u304c\u6559\u5ba4\u306b\u5165\u3063\u3066\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Ketika sedang membicarakan Yamada, pada akhirnya dia masuk ke ruang kelas.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">3</span><strong>\u65e9\u901f</strong>\uff08\u3055\u3063\u305d\u304f\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(segera / langsung (tanpa menunda))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u5317<rt>\u307b\u3063</rt></ruby><ruby>\u6d77<rt>\u304b\u3044</rt></ruby><ruby>\u9053<rt>\u3069\u3046</rt></ruby>\u306b\u6765\u3089\u308c\u308b\u306a\u3089\u3001<u>\u65e9\u901f</u>\u308f\u305f\u3057\u306e\u5bb6\u306b\u3082<ruby>\u5bc4<rt>\u3088</rt></ruby>\u3063\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Jika Anda bisa datang ke Hokkaido, segera mampir juga ke rumah saya, ya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u30a4\u30f3\u30bf\u30fc\u30cd\u30c3\u30c8\u3067<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u306b\u306a\u3063\u305f<ruby>\u4f50<rt>\u3055</rt></ruby><ruby>\u85e4<rt>\u3068\u3046</rt></ruby>\u3055\u3093\u3068\u306f\u3001<u>\u65e9\u901f</u>\u4f1a\u3063\u305f\u3053\u3068\u304c\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Dengan Sato yang menjadi teman lewat internet, saya segera belum pernah bertemu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <ruby>\u6751<rt>\u3080\u3089</rt></ruby><ruby>\u4e0a<rt>\u304b\u307f</rt></ruby>\u3055\u3093\u306b\u3044\u305f\u3060\u3044\u305f\u304b\u308f\u3044\u3044\u304a\u82b1\u3001<u>\u65e9\u901f</u>\u308f\u305f\u3057\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u306b<ruby>\u98fe<rt>\u304b\u3056</rt></ruby>\u308a\u307e\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Bunga cantik pemberian Saudari Murakami langsung/segera saya pajang di kamar saya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <u>\u65e9\u901f</u>\u3044\u3044\u306e\u3067\u3001\u6642\u9593\u304c\u3042\u308b\u3068\u304d\u306b\u96fb\u8a71\u3057\u3066\u304f\u3060\u3055\u3044\u3002</div>\n      <div class=\"q-id-trans\">Segera tidak apa-apa kok, jadi silakan telepon saat ada waktu.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">4</span><strong>\u4eca\u306b\u3082</strong>\uff08\u3044\u307e\u306b\u3082\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(sebentar lagi / hampir saja (terjadi seketika))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5927\u96e8\u306e\u305b\u3044\u3067\u3001\u5ddd\u306e\u6c34\u304c<u>\u4eca\u306b\u3082</u>\u3042\u3075\u308c\u305d\u3046\u3067\u5371\u967a\u3060\u3002</div>\n      <div class=\"q-id-trans\">Akibat hujan lebat, air sungai hampir saja meluap sehingga berbahaya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u7d04\u675f\u306e\u6642\u9593\u306b\u306a\u3063\u3066\u3082\u53cb\u4eba\u304c\u6765\u306a\u3044\u306e\u3067\u3001<u>\u4eca\u306b\u3082</u>\u30d1\u30fc\u30c6\u30a3\u30fc\u3092\u59cb\u3081\u308b\u3053\u3068\u306b\u3057\u305f\u3002</div>\n      <div class=\"q-id-trans\">Meskipun sudah tiba waktu janji teman tidak datang, kami memutuskan untuk hampir saja memulai pesta.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u3053\u306e\u30d1\u30bd\u30b3\u30f3\u306f\u5148\u9031\u8cb7\u3063\u305f\u306e\u306b\u3001<u>\u4eca\u306b\u3082</u><ruby>\u58ca<rt>\u3053\u308f</rt></ruby>\u308c\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Padahal komputer ini baru dibeli minggu lalu, hampir saja sudah rusak.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u8d64\u3044<ruby>\u53e3<rt>\u304f\u3061</rt></ruby><ruby>\u7d05<rt>\u3079\u306b</rt></ruby>\u3092<u>\u4eca\u306b\u3082</u>\u4f7f\u3063\u305f\u304c\u3001\u610f\u5916\u3068<ruby>\u4f3c<rt>\u306b</rt></ruby><ruby>\u5408<rt>\u3042</rt></ruby>\u3063\u3066\u3044\u3066\u3068\u3066\u3082\u6c17\u306b\u5165\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya hampir saja memakai lipstik merah, tetapi ternyata cocok dan saya sangat menyukainya.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">5</span><strong>\u304d\u3061\u3093\u3068</strong> <small style=\"color:#1b5e20; font-weight:600;\">(dengan rapi / tertib / teratur)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <ruby>\u9759<rt>\u3057\u305a</rt></ruby>\u304b\u306a\u5c71\u306b\u767b\u3063\u3066\u3001\u4e00\u4eba\u3067<u>\u304d\u3061\u3093\u3068</u><ruby>\u904e<rt>\u3059</rt></ruby>\u3054\u3059\u6642\u9593\u304c\u597d\u304d\u3060\u3002</div>\n      <div class=\"q-id-trans\">Saya suka waktu menghabiskan diri sendiri dengan rapi setelah mendaki gunung yang sunyi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u4ed5\u4e8b\u3092\u3059\u308b\u305f\u3081\u306e<ruby>\u90e8<rt>\u3078</rt></ruby><ruby>\u5c4b<rt>\u3084</rt></ruby>\u306f\u3001\u3044\u3064\u3082<u>\u304d\u3061\u3093\u3068</u><ruby>\u7247<rt>\u304b\u305f</rt></ruby><ruby>\u4ed8<rt>\u3065</rt></ruby>\u3051\u3066\u3044\u307e\u3059\u3002</div>\n      <div class=\"q-id-trans\">Ruangan untuk bekerja selalu saya bereskan dengan rapi.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5e30\u308a\u304c<ruby>\u9045<rt>\u304a\u305d</rt></ruby>\u304f\u306a\u3063\u305f\u65e5\u306f\u3001\u30b7\u30e3\u30ef\u30fc\u3082<ruby>\u6d74<rt>\u3042</rt></ruby>\u3073\u306a\u3044\u3067<u>\u304d\u3061\u3093\u3068</u>\u5bdd\u3066\u3057\u307e\u3046\u3002</div>\n      <div class=\"q-id-trans\">Pada hari pulang larut, saya tidur dengan rapi tanpa mandi sekalipun.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u5f7c\u5973\u306f<u>\u304d\u3061\u3093\u3068</u>\u3057\u305f\u4eba\u3060\u304b\u3089\u3001\u3044\u3064\u3082\u6388\u696d\u306b\u9045\u523b\u3092\u3057\u3066\u304f\u308b\u3002</div>\n      <div class=\"q-id-trans\">Karena dia orang yang rapi/disiplin, dia selalu datang terlambat ke kelas.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">6</span><strong><ruby>\u5f53<rt>\u3068\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby></strong>\uff08\u3068\u3046\u305c\u3093\uff09 <small style=\"color:#1b5e20; font-weight:600;\">(tentu saja / sewajarnya)</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u3053\u306e\u5c71\u306e\u4e00\u756a\u4e0a\u306b\u7740\u304f\u305f\u3081\u306b\u4f55\u65e5\u3082\u304b\u3051\u3066\u3001<u><ruby>\u5f53<rt>\u3068\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby></u>\u6b69\u3044\u305f\u3002</div>\n      <div class=\"q-id-trans\">Untuk tiba di puncak gunung ini, saya berjalan tentu saja selama berhari-hari.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u590f\u4f11\u307f\u306f\u65e5\u672c\u3092\u65c5\u884c\u3057\u3066\u3001<u><ruby>\u5f53<rt>\u3068\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby></u>\u697d\u3057\u3080\u3053\u3068\u304c\u3067\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Liburan musim panas berwisata ke Jepang dan tentu saja dapat menikmatinya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u99c5\u306b\u884c\u3063\u305f\u308910\u5e74\u3076\u308a\u306b<u><ruby>\u5f53<rt>\u3068\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby></u>\u53cb\u4eba\u306b\u4f1a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saat pergi ke stasiun, setelah 10 tahun saya tentu saja bertemu teman.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u60aa\u3044\u3053\u3068\u3092\u3057\u305f\u306e\u306a\u3089\u3001<u><ruby>\u5f53<rt>\u3068\u3046</rt></ruby><ruby>\u7136<rt>\u305c\u3093</rt></ruby></u>\u76f8\u624b\u306b<ruby>\u8b1d<rt>\u3042\u3084\u307e</rt></ruby>\u308b\u3079\u304d\u3060\u3002</div>\n      <div class=\"q-id-trans\">Kalau sudah berbuat salah, tentu saja seharusnya meminta maaf kepada pihak yang dirugikan.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">7</span><strong>\u304d\u3063\u3068</strong> <small style=\"color:#1b5e20; font-weight:600;\">(pasti / tentu (dugaan kuat))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u5f7c\u306f\u3001<u>\u304d\u3063\u3068</u>\u7d04\u675f\u3092\u5b88\u3063\u3066\u304f\u308c\u308b\u3060\u308d\u3046\u3002</div>\n      <div class=\"q-id-trans\">Dia pasti akan menepati janjinya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. <ruby>\u4e2d<rt>\u306a\u304b</rt></ruby><ruby>\u672c<rt>\u3082\u3068</rt></ruby>\u3055\u3093\u306f\u30013\u4eba\u5206\u306e\u6599\u7406\u3092\u4e00\u4eba\u3067<u>\u304d\u3063\u3068</u>\u98df\u3079\u3066\u3057\u307e\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saudara Nakamoto pasti menghabiskan masakan porsi 3 orang sendirian.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u8d70\u3063\u3066\u304d\u305f\u8eca\u306b\u3076\u3064\u304b\u3063\u305f\u306e\u306b\u3001<u>\u304d\u3063\u3068</u>\u75db\u304f\u306a\u304b\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Padahal tertabrak mobil yang melaju, pasti tidak sakit.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u4e45\u3057\u3076\u308a\u306b\u98df\u3079\u308b\u6bcd\u306e\u6599\u7406\u306f\u3001<u>\u304d\u3063\u3068</u>\u304a\u3044\u3057\u304f\u611f\u3058\u3089\u308c\u305f\u3002</div>\n      <div class=\"q-id-trans\">Masakan ibu yang dimakan setelah sekian lama pasti terasa lezat.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">8</span><strong>\u3068\u3046\u3068\u3046</strong> <small style=\"color:#1b5e20; font-weight:600;\">(akhirnya (setelah proses panjang))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. \u65e5\u672c\u5168\u56fd\u3092<ruby>\u5468<rt>\u307e\u308f</rt></ruby>\u308b\u65c5\u884c\u3092\u3059\u308b\u306e\u3067\u3001<u>\u3068\u3046\u3068\u3046</u>\u5bb6\u306b\u306f\u3044\u307e\u305b\u3093\u3002</div>\n      <div class=\"q-id-trans\">Karena akan melakukan perjalanan berkeliling ke seluruh Jepang, akhirnya saya tidak ada di rumah.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u304a<ruby>\u8179<rt>\u306a\u304b</rt></ruby>\u304c\u7a7a\u3044\u305f\u304b\u3089\u3001<u>\u3068\u3046\u3068\u3046</u>\u591c\u3054\u98ef\u3092\u4f5c\u308d\u3046\u3002</div>\n      <div class=\"q-id-trans\">Karena perut lapar, akhirnya ayo buat makan malam.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. \u5f1f\u306e\u8eab\u9577\u304c\u4f38\u3073\u7d9a\u3051\u3066\u3001<u>\u3068\u3046\u3068\u3046</u>\u308f\u305f\u3057\u3088\u308a\u3082\u9ad8\u304f\u306a\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Tinggi badan adik laki-laki terus bertambah, dan akhirnya menjadi lebih tinggi daripada saya.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. <ruby>\u5bb6<rt>\u304b</rt></ruby><ruby>\u65cf<rt>\u305e\u304f</rt></ruby>\u3068<ruby>\u96e2<rt>\u306f\u306a</rt></ruby>\u308c\u3066\u4e00\u4eba\u3067\u4f4f\u3093\u3067\u3044\u308b\u304c\u3001<u>\u3068\u3046\u3068\u3046</u><ruby>\u4e21<rt>\u308a\u3087\u3046</rt></ruby><ruby>\u89aa<rt>\u3057\u3093</rt></ruby>\u304b\u3089\u98df\u3079\u7269\u3084\u670d\u306e\u30d7\u30ec\u30bc\u30f3\u30c8\u304c<ruby>\u5c4a<rt>\u3068\u3069</rt></ruby>\u304f\u3002</div>\n      <div class=\"q-id-trans\">Meski tinggal sendiri terpisah dari keluarga, akhirnya kiriman hadiah makanan dan baju dari orang tua selalu tiba.</div>\n    </div>\n  </div>\n</div>\n<div class=\"question-block\">\n  <div class=\"q-jp\"><span class=\"q-num\">9</span><strong>\u305a\u3063\u3068</strong> <small style=\"color:#1b5e20; font-weight:600;\">(terus-menerus (dalam rentang waktu lama))</small></div>\n  <div class=\"q-options\">\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">1. <u>\u305a\u3063\u3068</u><ruby>\u5fdc<rt>\u304a\u3046</rt></ruby><ruby>\u63f4<rt>\u3048\u3093</rt></ruby>\u3057\u3066\u3044\u305f\u30d0\u30b9\u30b1\u30c3\u30c8\u30dc\u30fc\u30eb\u9078\u624b\u306b\u4f1a\u3046\u3053\u3068\u304c\u3067\u304d\u305f\u3002</div>\n      <div class=\"q-id-trans\">Saya dapat bertemu dengan pemain bola basket yang sudah terus-menerus saya dukung.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">2. \u3053\u306e\u30ec\u30b9\u30c8\u30e9\u30f3\u306b\u884c\u304f\u306b\u306f\u3001<u>\u305a\u3063\u3068</u>\u4e88\u7d04\u3092\u3068\u3089\u306a\u3044\u3068\u3044\u3051\u306a\u3044\u3002</div>\n      <div class=\"q-id-trans\">Untuk pergi ke restoran ini, harus terus-menerus memesan tempat terlebih dahulu.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">3. <u>\u305a\u3063\u3068</u>\u99c5\u3067\u4f1a\u3063\u305f<ruby>\u53cb<rt>\u3068\u3082</rt></ruby><ruby>\u9054<rt>\u3060\u3061</rt></ruby>\u3068\u3001\u305d\u306e\u307e\u307e\u591c\u3054\u98ef\u3092\u98df\u3079\u306b\u884c\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Bersama teman yang terus-menerus saya temui di stasiun, kami langsung pergi makan malam.</div>\n    </div>\n    <div class=\"opt-block\">\n      <div class=\"q-jp\">4. \u307f\u3093\u306a\u304c\u624b\u4f1d\u3063\u3066\u304f\u308c\u305f\u304a\u304b\u3052\u3067\u3001<u>\u305a\u3063\u3068</u>\u4ed5\u4e8b\u304c\u7d42\u308f\u3063\u305f\u3002</div>\n      <div class=\"q-id-trans\">Berkat bantuan semua orang, pekerjaan selesai dengan terus-menerus.</div>\n    </div>\n  </div>\n</div>\n<div class=\"answer-box\"><strong>Kunci Jawaban (\u6b63\u7b54):</strong> \u2460 2\uff081 \u3061\u3063\u3068\u3082 [sama sekali tidak]\u30fb3 \u3068\u3046\u3068\u3046 [akhirnya]\u30fb4 \u5fc5\u305a\u3057\u3082 [belum tentu]\uff09\u3000\u2461 3\uff081 \u3061\u3063\u3068\u3082 [sama sekali tidak]\u30fb2 \u5f53\u7136 [tentu saja]\u30fb4 \u3061\u3087\u3046\u3069 [tepat saat]\uff09\u3000\u2462 3\uff081 \u305c\u3072 [pastikan/sungguh-sungguh]\u30fb2 \u307e\u3060 [masih belum]\u30fb4 \u3044\u3064\u3067\u3082 [kapan saja]\uff09\u3000\u2463 1\uff082 \u5148\u306b [lebih dulu]\u30fb3 \u3059\u3050\u306b [segera]\u30fb4 \u521d\u3081\u3066 [pertama kali]\uff09\u3000\u2464 2\uff081 \u306e\u3093\u3073\u308a [santai]\u30fb3 \u3059\u3050\u306b\u30fb\u65e9\u3081\u306b [segera/lebih awal]\u30fb4 \u3060\u3089\u3057\u306a\u3044 [ceroboh/berantakan]\uff09\u3000\u2465 4\uff081 \u5927\u5206 [cukup lama/jauh]\u30fb2 \u5341\u5206 [sepuasnya]\u30fb3 \u5076\u7136 [kebetulan]\uff09\u3000\u2466 1\uff082 \u307b\u3068\u3093\u3069 [hampir seluruhnya]\u30fb3 \u5c11\u3057\u3082 [sedikit pun tidak]\u30fb4 \u7279\u306b [khususnya]\uff09\u3000\u2467 3\uff081 \u3057\u3070\u3089\u304f [sementara waktu]\u30fb2 \u305d\u308d\u305d\u308d [sudah waktunya]\u30fb4 \u3068\u304d\u3069\u304d [kadang-kadang]\uff09\u3000\u2468 1\uff082 \u307e\u305a [pertama-tama]\u30fb3 \u3055\u3063\u304d [tadi]\u30fb4 \u3059\u3050\u306b [langsung/segera]\uff09</div>\n</section>\n";
